  function getModulePath(filepath) {
    if (filepath.search(/^http:|https:\/\//i) == -1) {
      //var loc = window.location.href,    //extend
      //	path = loc.substr(0,loc.lastIndexOf("/"));
      //filepath = filepath.replace(/\./g, "/");
      filepath =
        milo.config.loaderPath +
        filepath.replace(/\./g, "/") +
        ".js" +
        "?" +
        milo.config.version;
    }
    return filepath;
  }

  /**
   * 获取模块名称
   * 以http://开头的，为fullpath
   * 其它的均视为相对路径
