  extend(dom, {
    /**
     * 判断浏览器类型
     */
    browser: {
      /**
       * 获取版本号
       */
      version: (userAgent.match(/.+(?:rv|it|ra|ie)[\/: ]([\d.]+)/) || [
        0,
