     */
    getSeverDateTime: function () {
      var xhr = window.ActiveXObject
        ? new ActiveXObject("Microsoft.XMLHTTP")
        : new XMLHttpRequest();
      xhr.open("HEAD", window.location.href, false);
      xhr.send();
      var d = new Date(xhr.getResponseHeader("Date"));

