define("ams.atm",function(){
	//降域，方便iframe中转页通信，判断来源
	// if(/(\.qq\.com)$/.test(document.location.host)){
	// 	document.domain="qq.com";
	// }
	var comm={
		atmUrl:"https://ams.game.qq.com/log?sCloudApiName=atm",//要请求的atm后台地址
		crossDomainUrl:location.protocol+"//ams.game.qq.com/ams/postATM.html"//中转页面地址
	};
	//整合对象
	var assignValue=function(defaultData,data){
		for(var k in data){
			if(data[k] !== undefined){
				defaultData[k]=data[k];
			}else if(defaultData[k] === undefined){
				defaultData[k]="";
			}
		}
		return defaultData;
	}
	var getGameId = function getGameId(s_url) {
		var url = s_url || (window && window.location.host) || '';
		var gameId = url.replace(/(\w+?)\.qq\.com/ig, "$1");
		return gameId == url ? "" : gameId;
	}; 
	var ATM={
		//获取正确的uin
		getUin:function(){
			var t =  milo.cookie.get("IED_LOG_INFO2"),
				IED_LOG_INFO2 = (t==null) ? null : milo.unSerialize(t);
			if(IED_LOG_INFO2 == null){
				return '';
			}
			uin = IED_LOG_INFO2.userUin;
			return (!isNaN(uin)) ? uin : milo.cookie.get("uin");
		},
		//组织数据和参数,包括但不限于校验，过滤等
		reportATM:function(data, callback){
			try{
				var originalData = {
					"fromappid": 38,
					"frommoduletype": 1,
					"toreturncode": 1,
					"result": 1,
					"struserid": milo.cookie.get("openid") || this.getUin(),//微信openid或者qq号
					//"timecost": (new Date().getTime()) - startTime,
					"serialtime": parseInt(new Date().getTime() / 1000)
				}
				if(typeof data == "object"){
					originalData=assignValue(originalData, data);
				}
				//amesvr
				if("string"==typeof originalData.tomoduletype){
					var tonode=originalData.tomoduletype;
					originalData.tomoduletype = originalData.tomoduletype.indexOf('amesvr') > -1 ? 55 : 32;
					//增加tonode上报
					if(!originalData.tonode){
						if(!/^(http)/.test(tonode)){
							tonode=location.protocol+"//"+tonode;
						}
						originalData.tonode=tonode;
					}
				}

				//活动id或cgi
				if(!originalData.actid || !/^[1-9](\d)*$/.test(originalData.actid)){//没用活动号，或者活动号非法，用href表示cgi
					//=========filter cgi    Start=============
					var sCgi=originalData.cgi || location.href;
					if(sCgi){
						try{
							// // 先灰度ymzx
							// if(/ymzx\.qq\.com/.test(sCgi)){
								originalData.cgi=sCgi.match(/^([^\?^\#]+)(\?[^\#]*)*(\#.*)*$/)[1];
								delete originalData.actid;
							// }else{
							// 	// 其它先归0
							// 	originalData.actid = 0;
							// }

						}catch(e){
							//sCgi=location.href;
						}
					}
					//=========filter  cgi    End=============
				}

				this.postATM(originalData, comm.atmUrl, function(res){
					if(typeof callback == "function"){
						callback(res);
					}
				},3000);
			}catch(e){
				return;
			}
		},
		reportVist:function(callback) {
			try {

				var url = window.location.href;

				var index1 = url.indexOf('?');
				if (index1 >= 0) {
					url = url.substring(0,index1);
				}
				var index2 = url.indexOf('#');
				if (index2 >= 0) {
					url=url.substring(0,index2);
				}
				var data = {
					// cgi: url,
					// actid:url,
					errormsg: '访问成功',
					fromappid: 38, // milo 应用id
					frommoduletype: 1, // 其他
					toappid: 38,
					tomoduletype:1,
					tointer: 1,
					businesstype: getGameId(),
					struserid: milo.cookie.get("openid") || this.getUin(), //微信openid或者qq号
					serialtime: parseInt(new Date().getTime() / 1000),
					result: 0,
					toreturncode: 0 
				}
				// 先灰度ymzx上报准确url
				// if(/ymzx\.qq\.com/.test(location.href)){
					data.cgi = url;
				// }else{
				// 	data.actid = 0;
				// }
				this.postATM(data, comm.atmUrl, function (res) {
					if (typeof callback == 'function') {
						callback(res);
					}
				}, 3000);
			} catch (e) {
				return;
			}
		},
		// 增加不阻塞上报模式 add by weiztang 20240104
		postATMByBeacon:function(data, url){
			try{
				navigator.sendBeacon(url, JSON.stringify(data));
			}catch(e){

			}
		},
		//发起请求，兼容IE低版本浏览器
		postATM:function(data,url,callback,outTime){
			//IE浏览器单独处理
			if(milo.browser.msie){
				this.postATMForIE(data,url,callback,outTime);
				return;
			}
			if(!callback && navigator.sendBeacon){
				this.postATMByBeacon(data,url);
				return;
			}
			try{
				var timeout; //用来作超时处理

				var xmlhttp;
				if (window.XMLHttpRequest){
					xmlhttp=new XMLHttpRequest();
				}else{
					xmlhttp=new ActiveXObject("Microsoft.XMLHTTP");
				}
				xmlhttp.onreadystatechange=function(){
					if (xmlhttp.readyState==4 && xmlhttp.status==200){
						if(typeof callback == "function"){
							//成功则清除超时设置
							if(timeout){
								clearTimeout(timeout);
							}
							callback(xmlhttp.responseText);
						}
					}
				}
				xmlhttp.open("post",url,true);
				xmlhttp.send(JSON.stringify(data));

				//超时设置
				timeout = setTimeout(function(){
					if (xmlhttp) xmlhttp.abort();
				}, outTime);
			}catch(e){

			}
		},
		//IE下请求ATM，通过中转页面，防止安全提示
		postATMForIE:function(data, url, callback, outTime){
			//postATM.html下不再发起请求
			if(/^(https?)\:\/\/ams.game.qq.com\/ams\/postATM\.html/.test(location.href)){
				return;
			}
			var pAIFrame=null;
			if(!g("postATMFrame")){
				pAIFrame = document.createElement("iframe");
				pAIFrame.id = "postATMFrame";
				pAIFrame.name = "postATMFrame";
				pAIFrame.scrolling="no";
				pAIFrame.frameBorder ="0";
				pAIFrame.style.width="0px";
				pAIFrame.style.overflow="hidden";
				pAIFrame.style.display ="none";
				pAIFrame.style.position="absolute";
				document.body.appendChild(pAIFrame);
			}else{
				pAIFrame=g("postATMFrame");
			}
			//延迟发送时间，排队，防止请求被canceled
			//假设每一个请求需要2000ms
			var delayTime=parseInt(pAIFrame.getAttribute("data-delay") || 0);//delayTime标识下一个可以发送请求的时间点（用时间戳表示）
			var delayRequest=0;//下一个可以发送请求的时间点相对于当前时间的diff
			//请求ATM动作
			var requestFunc=function(){
				var postATMUrl=comm.crossDomainUrl;//中转页面
				postATMUrl+="?_t=" + parseInt((Math.random()*100000)) + "&url="+encodeURIComponent(url)+"&data="+encodeURIComponent(JSON.stringify(data))+"&timeout="+ (outTime||0);
				pAIFrame.src=postATMUrl;
			}
			//如果有延迟时间并且延迟时间在当前时间之后，则延迟上报
			if(delayTime && delayTime>new Date().getTime()){
				delayTime+=2000;
				delayRequest=(delayTime-new Date().getTime());
				setTimeout(function(){
					requestFunc();
				},delayRequest)
			}else{//否则立即上报
				requestFunc();
				delayTime=new Date().getTime()+2000;
			}
			pAIFrame.setAttribute("data-delay",delayTime);
		}
	}
	return ATM;
})

