//开启专属大区后过滤函数

function filterArea(areaId) {
    var arr_areaId = new Array();
    var jareaId = new Array();
    var area_server = new Array();
    var oAServer = new Object();
    var jServer = new Array();
    var recommend = new Array();
    var newj = new Array();
    var colSer = new Array();
    var cIndex = 0;

    arr_areaId = areaId.split("|");
    var arr_index = 0;
    for (var i = 0; i < arrAreaShowList.length; i++) {
        var jaId = arrAreaShowList[i]['sAreaID'];
        var bo = in_array(jaId, arr_areaId);
        if (bo) {
            jareaId[arr_index] = new Array();
            jareaId[arr_index]['sAreaID'] = arrAreaShowList[i]['sAreaID'];
            jareaId[arr_index]['sAreaName'] = arrAreaShowList[i]['sAreaName'];
            jareaId[arr_index]['sNetFlag'] = arrAreaShowList[i]['sNetFlag'];
            arr_index++;
        }
    }
