    console.log("arrAreaShowList.length:"+arrAreaShowList.length);
    //document.write(JSON_area[0]['sAreaID']+"<br/>");
    
    var str = '';
    for (var j = 0; j < arrAreaShowList.length; j++) {
        var sId = arrAreaShowList[j]['sAreaID'];
        //ADD BY RECAHRDYANG
        arrServerList = JSON_area_server[sId];
        
        if(parseInt(sId)==5095140)
        {
            arrTemp1 = new Array();
            arrTemp2 = new Array();
            arrTemp3 = new Array();
            
            arrTemp1 = arrServerList.reverse();
            
            arrTemp2 = JSON_area_server[6740044];
            
            arrTemp3 = JSON_area_server[7470368];
            
            if(arrTemp3)
            {
                arrTemp3 = arrTemp3.reverse();
                arrTemp2 = arrTemp2.reverse();
                    
                arrServerList = arrTemp3.concat(arrTemp2,arrTemp1);
            }
        }
        if(parseInt(sId)==7609651)
        {
            arrTemp4 = new Array();
            arrTemp5 = new Array();
            arrTemp4 = arrServerList.reverse();
            arrTemp5 = JSON_area_server[7609753];
            
            if(arrTemp5)
            {
                arrTemp5 = arrTemp5.reverse();
                
                arrServerList = arrTemp5.concat(arrTemp4);
            }
        }
        // if (parseInt(sId)==7609527){//公测
        //     console.log('公测');
        //     console.log(JSON_area_server[7609527]);
        //     arrTemp6 = new Array();
        //     arrTemp6 = JSON_area_server[7609527];
        //     arrTemp6 = arrTemp6.splice(1000);
        //     arrServerList = arrTemp6.reverse();
        //     console.log(arrServerList);
        //
        // }
        // if (parseInt(sId)==7609528){//公测1000+
        //     console.log('1000+')
        //     console.log(JSON_area_server[7609527]);
        //     arrTemp7 = new Array();
        //     arrTemp7 = JSON_area_server[7609527];
        //     arrTemp7 = arrTemp6.slice(999);
        //     arrServerList = arrTemp6.reverse();
        // }
        
        str += sId + ":[" + arrServerList + "],";
        if (typeof(arrServerList) != "undefined" && arrServerList.length != 0) {
            for (var s = 0; s < arrServerList.length; s++) {
                osId = arrServerList[s];
                oAServer[osId] = JSON_server[osId];
            }
        }
    }
    str = str.substring(0, str.length - 1);
    str = "{" + str + "}";
    str = eval('(' + str + ')');
    JSON_server = oAServer; //重写server数组
    JSON_area_server = str; //重写大区对应server数组
    for (var u = 0; u < arrAreaShowList.length; u++) {
        var sId = arrAreaShowList[u]['sAreaID'];
