        var re = JSON_recommend[n];
        if (in_array(re, colSer)) {
            recommend[recommend_index] = re;
            recommend_index++;
        }
    }
    var new_index = 0;
    for (var m = 0; m < JSON_new.length; m++) {
        var ne = JSON_new[m];
        if (in_array(ne, colSer)) {
            newj[new_index] = ne;
