    JSON_recommend = recommend; //重写推荐server数组
    JSON_new = newj; //重写最新server数组

    //JSON_Telecom_iServerId,JSON_NetCom_iServerId,JSON_Crewel_iServerId首先判断是否存在，然后在重写
