//判断一个元素是否在一个数组函数 added by yalizhao 

function in_array(str, arr_json) {
    for (var i = 0; i < arr_json.length; i++) {
        if (typeof(arr_json[i]) != "undefined" && arr_json[i] != null) {
            if (arr_json[i] == str) {
                return true;
            }
        }
    }
    return false;
}

