                        jAreaStr = arrAreaShowList[i]['sAreaID'];
                    } else {
                        jAreaStr = jAreaStr + '|' + arrAreaShowList[i]['sAreaID'];
                    }
                }
                for (var m = 0; m < unionAreaId_arr.length; m++) {
                    jAreaStr = jAreaStr.replace(unionAreaId_arr[m], '');
                }
                filterArea(jAreaStr);
                $("#allServer").hide();
            }
        }
    }
}

