        if (configJs["getLastLogin"] == 1 && !(typeof(JSON_LAST) != "undefined" && sServerID == JSON_LAST.sOldServerId)) {
            if (typeof(JSON_SAVESVR) != "undefined" && JSON_SAVESVR != null) {
