        var sUrl = configJs["sLoginCgiUrl"] + "&sFrom=" + sFrom + "&sServerId=" + sServerID + sLoginCgiUrlParam + "&rd=" + Math.random();
        FileLoadManager.ajaxRequest({
            'url': sUrl,
            'showLoadingStr': '正在登录游戏...',
