                                    1=>'QQ群接口',  //javascript:window.top.G.qxer.open
                                    2=>'3366接口',  //javascript:sendMgpProxyCmd
                                    3=>'朋友接口',  //javascript:top.XY.AppLib.popUpFullFrame
                                    4=>'游戏人生接口', //javascript:parent.callBackForGame
