function QcGetLastServerIdList() {

    var sUrl = qcConfigJs["selfGetServerIdUrl"] + "?openid=" + milo.cookie.get("openid") + "&rd=" + Math.random();

    var qc_server_list = new Array();
    $.get(sUrl, function (result, statue) {
        var res = $.parseJSON(result);
        if (typeof(res) != 'undefined' && res != null && res.status != 'undefined') {
            if (res.status != 0) {
                console.log(res.message);
                // LoginManager.checkLogin(function(){
                //     getOldServerId();
                // })
                qc_server_list = GetLastLoginServerByCookies();
            } else if (typeof(res.env) != 'undefined' && res.env != null && res.env.length > 0) {
                
                for (var i=res.env.length-1; i>=0; i--) {
                    var last_server_id = parseInt(res.env[i].name, 10);
                    if (JSON_server[last_server_id]) {
                        qc_server_list.push(last_server_id);
                    }
                }
            }
        } else {
            console.log("get server_list error");
        }
        QcShowLastLoginServer(qc_server_list);
    })

    // qc_server_list = GetLastLoginServerByCookies();

    GetLastLoginServerSucc(qc_server_list);
}

