    forEach: function (haystack, callback) {
      var i = 0,
        length = haystack.length,
        name;

      if (length !== undefined) {
        for (; i < length; ) {
          if (callback.call(haystack[i], i, haystack[i++]) === false) {
            break;
          }
        }
      } else {
        for (name in haystack) {
