namespace("milo.loader");

(function (loader) {
  var __loading = null,
    loaded = {}, //是否下载
    loading = {}, //正在下载  下载前就建立，以处理同时多次请求，但此处写了，就对不住loaded了，需重构
    queue = [], //define的deps队列
    modulemap = {}; //加载队列
