   */
  loader[_defineMethodName] = function (name, deps, callback) {
    //无name参数时从文件名取name（urlcb回调中处理）
    //无deps，则[]
    if (!isString(name)) {
      callback = deps;
      deps = name;
      name = null;
    }

    if (!isArray(deps)) {
      callback = deps;
      deps = [];
    }

    //**callback非function 为object时，直接为name返回object（cb回调中）
    queue.push([name, deps, callback]);
    return undefined;
  };

  //jquery支持
  loader[_defineMethodName].amd = {
    //multiversion: true,
    //plugins: true,
    jQuery: true,
  };

  /**
