    script.type = "text/javascript";
    script.charset = charset;
    // var reqUrl = url
    // var isCros;
    // if (isObject(url)) {
    // 	reqUrl = url.url;
    // 	isCros = url.crossOrigin
    // }
    // script.src = reqUrl;
    script.src = url;
    // var shouldCross = /^(https?\:)?(\/\/)ossweb-img\.qq\.com/.test(reqUrl)
    // if (typeof isCros !== 'undefined') { // 如果显示的传入crossOrigin参数则以传参为准
    // 	shouldCross = isCros
