  function isMultiDomainHit(whiteList) {
    var domainList = whiteList.split(";");
    var isHit = false;
    for (var i = 0; i < domainList.length; i++) {
      var domain = domainList[i].replace(/(^\s*)|(\s*$)/g, "");
      if (domain == location.hostname) {
        isHit = true;
