    toDateTimeString: function (nd) {
      var dt = isDate(nd) ? nd : _d,
        h = dt.getHours(),
        i = dt.getMinutes(),
        s = dt.getSeconds(),
        a = [];
      a.push(h.toString().length < 2 ? "0" + h : h);
      a.push(i.toString().length < 2 ? "0" + i : i);
      a.push(s.toString().length < 2 ? "0" + s : s);
      return date.toDateString.apply(this, arguments) + " " + a.join(":");
