		postMessageProxy = {
			isLegalOrigin: function(url) {
				// 检测是否合法域名
  				// 合法域名列表
  				var whiteDomain = ['qq.com']; // 白名单
  				var blackDomain = ['p.imtt.qq.com']; // 黑名单
  				var isLegal = false;
  				var regStr = '^(https\\:\\/\\/|http\\:\\/\\/|\\/\\/|)([0-9a-z-A-Z]+\\.)*reg(\\:[0-9]*){0,1}(\\/{1,2}.*){0,1}$';
  				var regWhite = null;
  				// 判断白名单
  				for (var i = 0; i < whiteDomain.length; i++) {
  				  regWhite = new RegExp(regStr.replace('reg', whiteDomain[i].replace(/\./g, '\\.')));
  				  if (regWhite.test(url)) {
  				    isLegal = true;
  				  }
  				}
  				if (isLegal == false) {
  				  // 不在白名单
  				  return false;
  				}
  				// 判断黑名单
  				var regBlack = null;
  				for (var i = 0; i < blackDomain.length; i++) {
  				  regBlack = new RegExp(regStr.replace('reg', blackDomain[i].replace(/\./g, '\\.')));
  				  if (regBlack.test(url)) {
  				    isLegal = false;
  				  }
  				}
  				return isLegal;
			},
			addEventListener: function(actionName, callbackName) {
				var self = this;
				if ('function' === typeof window.postMessage) {
					window.addEventListener('message', function(e) {
						if (!self.isLegalOrigin(e.origin)) {
							// 非法来源
							return;
						}
						var eData = {};
						if (!e.data) {
							// 没有数据
							return;
						}
						try {
							if ("string" === typeof e.data) {
								eData = JSON.parse(e.data);
							} else {
								eData = e.data;
							}

							if (eData && eData.callbackName == callbackName && eData.action == actionName) {
								const data = eData.data || "";
								isFunction(window[eData.callbackName]) && window[eData.callbackName](data);
							}
						} catch(e) {
							console.log("addEventListener Error", e);
						}
					}, false);
				}
			}
		},
