LoginManager.loginByWegame=function(opt,callback){
	var self=this;
	// wegame login report
	ATM.reportATM({
		toappid: 38,
		tomoduletype: 21,
		tointer: 4,
		toreturncode: 0,
		businesstype: comm.getGameId(),
		result: 0,
		cgi: location.href,
		errormsg: 'wegame pc login'
	});
	var logOption={};
	extendLess(logOption,option);
	extendLess(logOption,opt);
	//wegame登录参数
	var wegameParams=option.oWegameParams || {
		client_id:'7019928239',//应用id
		redirect_uri:'https://milo.qq.com/comm-htdocs/login/wegame_redirect.html',//回调地址
		rail_game_id:'2000108',//游戏id
		scope:'openid profile',//作用域，可多选，空格分隔
		state:'STATE',//防csrf
		lang:'ZH_CN'//语言，默认为中文(ZH_CN)
	};
	if(opt.oWegameParams){
		extendLess(wegameParams,opt.oWegameParams);
	}

	if(opt && opt.needReloadPage){
		logOption.needReloadPage=opt.needReloadPage;
	}else{
		logOption.needReloadPage = (isFunction(callback)) ? false : logOption.needReloadPage;
	}

	//记录登录之前的uin
	var oldUin=milo.cookie.get('uin');
	//callback,内嵌页redirect_uri拿到code传到父页面通信鉴权
	window.wegameCallback=function(codeOption){
		wegameFrame.showTitle(true);
		console.log(codeOption);
		if(!codeOption || !codeOption.code){
			alert("抱歉，参数错误，请重新登录");
			wegameFrame.close();
			return;
		}
		if(codeOption.state != wegameParams.state){
			alert("抱歉，来源校验错误，请重新登录");
			wegameFrame.close();
			return;
		}

		//鉴权函数
		var wegameCallbackName="wegameCallback_"+Math.ceil(10000*Math.random());
		window[wegameCallbackName]=function(userInfo){
			if(0!=userInfo.errorCode){//出错了
				alert("抱歉，请重新登录");
				wegameFrame.close();
				return;
			}
			//判断现在的uin和oldUin是否一致，不一致则清除pt登录态。否则影响其它页面逻辑
			if(oldUin && milo.cookie.get('uin') && oldUin !== milo.cookie.get('uin')){
				milo.cookie.clear('IED_LOG_INFO2','qq.com','/');
				self.clearPtStatus();
			}
			var logInfo={
				openid:milo.cookie.get("openid"),
				//userUin:'',
				nickName:userInfo.nickName,
				nickname: userInfo.nickName ? decodeURIComponent(userInfo.nickName): '',
				userLoginTime:parseInt(new Date().getTime()/1000),
				loginType:'wg',
				logtype: 'wg',
				expires:86400
			}
			var value = milo.serialize(logInfo);
			milo.cookie.set("IED_LOG_INFO2_WG",value,600,location.host,"/");
			//头像
			if(userInfo.face){
				comm.storeUserFace(logInfo.openid,userInfo.face);
			}
			//回调，不刷新页面
			if (!logOption.needReloadPage) {
				//先关闭弹框
				wegameFrame.close();
				//执行回调
				var isLogin = comm.checkUserLogined();
				if(isLogin){
					cb.loginedCallback();
					if (isFunction(callback))  callback();
				}else{
					cb.unloginCallback();
				}
			}else{
				//刷新页面
				window.location.reload();
			}
		}

		//code换取access_token和openid等
		need('util.jquery',function($){
			var params={
				a:'wgCodeToRailId',
				wg_code:codeOption.code,
				appid:wegameParams.client_id,
				redirect_uri:wegameParams.redirect_uri
			}
			$.ajax({
				url:'https://ams.game.qq.com/ams/userLoginSvr?'+milo.serialize(params),
				type:"GET",
				dataType:'jsonp',
				success:function(retObj){
					if(0==retObj.iRet){
						var data=retObj;
						var expires_in=data.expires_in || 3600;
						milo.cookie.set("openid",data.openid,expires_in,location.host,"/");
						milo.cookie.set("access_token",data.access_token,expires_in,location.host,"/");
						milo.cookie.set("appid",wegameParams.client_id,86400,location.host,"/");
						milo.cookie.set("acctype","wg",86400,location.host,"/");
						milo.cookie.set("refresh_token",data.refresh_token,86400,location.host,"/");
						//鉴权API
						var loginApi='https://ams.game.qq.com/ams/userLoginSvr';
						loadScriptLogin(loginApi + '?callback=' + wegameCallbackName + '&acctype=' + 'wg' + '&appid=' + wegameParams.client_id + '&openid=' + data.openid + '&access_token=' + data.access_token, function(loaded){
						});
					}else{
						self.logout(function(){
							alert(retObj.sMsg);
							wegameFrame.close();
						});

					}
				},
				error:function(){

				}
			})
		})
	}

	var loginUrl='https://api.rail.tgp.qq.com/web/oauth2.0/login/authorize?response_type=code';
	var loginOpt={
		redirect_type:'self',
		state:wegameParams.state,
		client_id:wegameParams.client_id,
		rail_game_id:wegameParams.rail_game_id,
		lang:wegameParams.lang,
		scope:wegameParams.scope,
		redirect_uri:wegameParams.redirect_uri
	}
	//parent domain
	milo.cookie.set("milo_wegame_domain",location.protocol+"//"+location.host,600,'qq.com',"/");
	/*if(-1 == loginOpt.redirect_uri.indexOf('parent_domain=')){
		loginOpt.redirect_uri+=(loginOpt.redirect_uri.indexOf('?')>-1?'&':'?')+'parent_domain='+encodeURIComponent(location.protocol+"//"+location.host);
	}*/
	//loginOpt.redirect_uri=encodeURIComponent(loginOpt.redirect_uri);
	loginUrl+="&"+milo.serialize(loginOpt);
	//如果是QcWx联合登录，则返回loginUrl
	wegameFrame.show(loginUrl);
}
/**
 * wegame登录态续期
 * @param {function} successCallback 续期成功后的回调
 * @param {function} failCallback 续期失败的回调
 * @return {undefined}
 */
 LoginManager.refreshWegame=function(successCallback,failCallback){
 	var refresh_token=milo.cookie.get('refresh_token');
 	var appid=milo.cookie.get('appid');
 	var acctype=milo.cookie.get('acctype');
 	if(!refresh_token || !appid || 'wg' != acctype){
 		isFunction(failCallback) && failCallback('抱歉，请重新登录。');
 		return;
 	}
 	var loginUrl=comm.getCheckLoginUrl();
 	var wegameRefreshCbName='wegameRefresh_'+ Math.ceil(10000*Math.random());
 	window[wegameRefreshCbName]=function(retObj){
 		if(0==retObj.errorCode && retObj.isLogin){
 			var expires_in=retObj.expires_in || 3600;
 			milo.cookie.set('openid',retObj.openid,expires_in,location.host,'/');
 			milo.cookie.set('access_token',retObj.access_token,expires_in,location.host,'/');
 			milo.cookie.set('refresh_token',retObj.refresh_token,86400,location.host,'/');
 			var logInfo={
				openid:retObj.openid,
				nickName:retObj.nickName,
				userLoginTime:retObj.userLoginTime,
				loginType:'wg',
				expires:86400
			}
			var value = milo.serialize(logInfo);
			milo.cookie.set('IED_LOG_INFO2_WG',value,600,location.host,'/');
			isFunction(successCallback) && successCallback();
 		}else{
 			isFunction(failCallback) && failCallback(retObj.errorStr);
 		}
 	}
 	var params={
 		appid:appid,
 		acctype:acctype,
 		refresh_token:refresh_token,
 		callback:wegameRefreshCbName
 	}
	loadScriptLogin(loginUrl+'?'+milo.serialize(params),function(){});
 }

/**
 * 用户登陆
 * @param {function} callback 登陆成功后的回调（此参数如成立，则needReloadPage强制改为false）
 * @param {object} opt 登陆配置项
 * @return {undefined}
 */
LoginManager.login = function(callback, opt){
	var ptOption = {
		'appid' : '',
		'target' : 'top',
		's_url' : ''//刷新页面的时候需要
	};
	var logOption = {
		'gameId' : '',
		'appId' : '',
		'needMaskDiv':true,  //need edit
		'needReloadPage':true, //登录成功以后刷新页面
        'loginDivOffset':{left:0.5,top:0.5},
		'msg' : '正在获取登录信息，请稍候...',
        'loginedCallback':null,
		'type' : 'float',
		'loginFrame' : 'loginHTMLFrame',
		'css' : '',
		's_url' : '',
		'iUseQQConnect':1
	};

	if(typeof(callback) != 'function' && typeof(callback) == 'object'){
		opt = callback;
		callback = null;
	}

	extendLess(logOption, option);
	//extendLess(logOption, opt);
	extend(logOption, opt);
	if(logOption.iUseQQConnect){
		return this.qcLogin(callback,opt);
	}

	//add susahuang 2017/8/1
	if(typeof opt == "object" && opt.needReloadPage) {
		logOption.needReloadPage = opt.needReloadPage;
	}else{
		logOption.needReloadPage = (isFunction(callback)) ? false : logOption.needReloadPage;
	}
	logOption.gameId = (!logOption.gameId) ? comm.getGameId() : logOption.gameId;
	ptOption.appid = (!logOption.appId) ? comm.getAppId(logOption.gameId) : logOption.appId;
	ptOption.s_url = (!logOption.s_url) ? comm.getS_URL(logOption.needReloadPage) : logOption.s_url;
    ptOption.target = (logOption.needReloadPage) ? 'top' : 'self';
	ptOption.style = logOption.style ? logOption.style : '20';

	//pt 403
	if(new RegExp('(^|;)'+location.host+'($|;)').test(pt403DomainList.join(';'))){
		//命中当前域名
		if(logOption.needReloadPage){
			callback = (function(sFinalUrl){
				return function(){
					if(location.href == sFinalUrl){
						location.reload();
					}else{
						location.href = sFinalUrl;
					}
				}
			})(logOption.s_url);
			ptOption.target = 'self';
			logOption.needReloadPage = false;
			ptOption.s_url = location.protocol+'//milo.qq.com/comm-htdocs/login/logincallback.htm';
		}else{
			ptOption.s_url = location.protocol+'//milo.qq.com/comm-htdocs/login/logincallback.htm';
		}

	}


	try {
					// add by weiztang 20240104 增加pt下线上报
					ATM.reportATM({
						toappid: 38,
						tomoduletype: 21,
						tointer: 1,
						businesstype: comm.getGameId(),
						toreturncode: 0,
						result: 0,
						cgi: location.href,
						errormsg: 'pt iframe',
						serialtime: parseInt(new Date().getTime() / 1000),
					});
	} catch (error) {
			console.log(error)
	}




	//页游有很多页面，原先传了1，导致页面乱码
	//style支持的参数有： 20, 21, 32, 33
	if (ptOption.style!=20 || ptOption.style!=21 || ptOption.style!=32 || ptOption.style!=33 ){
		ptOption.style=20;
	}

	ptOption.daid = 8;

	//登录成功以后刷新页面
	if (!logOption.needReloadPage) {

		// 登录成功后的回调函数
		window["LoginedCallback"] = function(){
			var callbackName = 'jsonp' + milo.randomInt(100);
			comm.callbackLoginInfo(callbackName, function(IED_LOG_INFO2){
				if(logOption.type == "inner"){
					$('#milo_login_close').trigger('click');
				}else{
					Dialog.hide();
				}
				var isLogin = comm.checkUserLogined();
				if(isLogin){
					//EAS上报uin
					try{
						if(window.EAS && EAS.SendUinLog){
							EAS.SendUinLog();
						}
					}catch(e){}
					cb.loginedCallback();
					if (isFunction(callback))  callback();
				}else{
					cb.unloginCallback();
				}
			});

			var acctype = requestLoginParam('acctype') || milo.cookie.get('acctype');
			var appid = requestLoginParam('appid');
			var openid = requestLoginParam('openid');
			var access_token = requestLoginParam('acctype')=="wx"?requestLoginParam('access_token'):requestLoginParam('openkey');
			//判断登录方式，如果是qc，则从cookie中取相关cookie
			if("qc" == acctype || "ks" == acctype){
				appid=appid || milo.cookie.get('appid');
				openid=openid || milo.cookie.get('openid');
				access_token=access_token || milo.cookie.get('access_token');
			}
			if(acctype){
				loadScriptLogin(comm.getCheckLoginUrl(option.gameId) + '?callback=' + callbackName + '&acctype=' + acctype + '&appid=' + appid + '&openid=' + openid + '&access_token=' + access_token+"&game="+comm.getGameId(), function(loaded){
				});

			}else{
				loadScriptLogin(comm.getCheckLoginUrl(option.gameId) + '?callback=' + callbackName+"&game="+comm.getGameId(), function(loaded){
				});
			}
		}
	}

	//var acctype = milo.cookie.get('acctype')?milo.cookie.get('acctype'):requestLoginParam('acctype');



    if (logOption.type=="float"){
    	logOption.src = 'https://xui.ptlogin2.qq.com/cgi-bin/xlogin?proxy_url='+ location.protocol +'//game.qq.com/comm-htdocs/milo/proxy.html&' + milo.serialize(ptOption);
		logWin.openLoginDiv(logOption);
    	Dialog.show({id:'loginDiv',bgcolor:'#E6F5FF',PopzIndex:100002});
    }else if(logOption.type == "inner"){
		ptOption.hide_close_icon=1;
		g(logOption.loginFrame).src = 'https://xui.ptlogin2.qq.com/cgi-bin/xlogin?proxy_url='+ location.protocol +'//game.qq.com/comm-htdocs/milo/proxy.html&' + milo.serialize(ptOption);

	}
    else{
    	ptOption.style = 1;
    	ptOption.hide_title_bar = 1;
    	ptOption.hide_close_icon = 1;
    	if (logOption.css){
			ptOption.css = logOption.css;
        }
		g(logOption.loginFrame).src = 'https://xui.ptlogin2.qq.com/cgi-bin/xlogin?proxy_url='+ location.protocol +'//game.qq.com/comm-htdocs/milo/proxy.html&' + milo.serialize(ptOption);

    }

};
