/**
 * 用户注销
 * @param {function} callback 注销成功后的回调
 * @param {object} opt 登陆配置项
 * @return {undefined}
 */
LoginManager.logout = function(callback, opt){
	var logOption = {
		'freshWin' : '',
        'jumpUrl' : '',
		'needMaskDiv' : true,
		"showTip":true,
		'msg' : '亲爱的用户，您已经注销成功！',
		'isNotForceClearPt':false,//是否不强制退出pt,只清除cookie
		'loginDivOffset' : {
			'left':0.5,
			'top':0.5
		},
		isNotForceClearPt:false
	};

	extendLess(logOption, option);
	extendLess(logOption, opt);

	//opt传值showTip:false,则不显示
	if(logOption.showTip!==false){
		Dialog.show({
			sMsg : "亲爱的用户，您已经注销成功",
			sStyle : 'margin:0px;padding:0px;width:250px;height:40px;border:2px solid buttonface;background-color:#FFFFCC;font-size:12px;color:#000;text-align:center;line-height: 40px; ',
			bgcolor:'#E6F5FF'
		});
	}

	milo.cookie.clear('IED_LOG_INFO2', 'qq.com', '/');

	//清除微信相关的COOKIE
	milo.cookie.clear('openid', 'qq.com', '/');
	milo.cookie.clear('access_token', 'qq.com', '/');
	milo.cookie.clear('appid', 'qq.com', '/');
	milo.cookie.clear('acctype', 'qq.com', '/');
	milo.cookie.clear('wxcode', 'qq.com', '/');
	milo.cookie.clear('uin', 'qq.com', '/');
	milo.cookie.clear('skey', 'qq.com', '/');
  	milo.cookie.clear('iegams_refresh_token','qq.com','/');

	//当前域下再清一次
	milo.cookie.clear('IED_LOG_INFO2', location.host, '/');
	milo.cookie.clear('IED_LOG_INFO2_QC', location.host, '/');
	milo.cookie.clear('IED_LOG_INFO2_WG', location.host, '/');
	milo.cookie.clear('IED_LOG_INFO2_KS', location.host, '/');
	milo.cookie.clear('openid', location.host, '/');
	milo.cookie.clear('access_token', location.host, '/');
	milo.cookie.clear('refresh_token', location.host, '/');
	milo.cookie.clear('appid', location.host, '/');
	milo.cookie.clear('acctype', location.host, '/');
	milo.cookie.clear('wxcode', location.host, '/');

	milo.cookie.clear("login_origin", location.host, "/");


	//保证注销回调只执行一次
	var logoutCallbackLock=2;

	window["logoutWxCallback"] = window["logoutCallback"] = function(){
		logoutCallbackLock--;//减少一次，说明有一个域名下已经注销
		cb.unloginCallback();
		//保证注销回调只执行最后一次
		if (isFunction(callback) && 0==logoutCallbackLock){
			callback();
		}

		if(logOption.showTip!==false){
			Dialog.hide();
		}

		// 判断是否刷新，根据jumpUrl参数执行跳转操作
		if(logOption.freshWin){
			if(logOption.jumpUrl){
				window[logOption.freshWin].location.href = logOption.jumpUrl;
			}else{
				window[logOption.freshWin].location.reload();
			}
		}
	}

	// dickma：再用iframe再清除了cookie一次
	// iframe清除： p_skey  p_uin uin seky IED_LOG_INFO2 openid access_token acctype appid
	//  seky 有错，需要修改
	// 清除apps.game.qq.com下的cookie
	var oWxIFrame = document.createElement("iframe");
	oWxIFrame.id = "loginWxIframe";
	oWxIFrame.name = "loginWxIframe";
	oWxIFrame.scrolling="no";
	oWxIFrame.frameBorder ="0";
	oWxIFrame.style.display ="none";
	document.body.appendChild(oWxIFrame);
    oWxIFrame.src=location.protocol+"//apps.game.qq.com/ams/logout_wx.html";
	//清除game.qq.com下的cookie
	var sLogoutGameUrl = location.protocol+"//game.qq.com/act/logout.html";
	if(logOption.isNotForceClearPt){
		sLogoutGameUrl = sLogoutGameUrl + '?isNotForceClearPt=1';
	} 
	logWin.openLoginDiv({
		src :sLogoutGameUrl
	});

	if (!pageSupportDomain) {
		postMessageProxy.addEventListener("loginManager_logout_WX", "logoutWxCallback");
		postMessageProxy.addEventListener("loginManager_logout_QQ", "logoutCallback");
	}
};

/**
 * 检查是否登陆，并执行对应回调
 * @param {function} logincallback 已登陆的回调
 * @param {function} unlogincallback 未登陆的回调
 * @param {object} opt 登陆配置项
 * @return {undefined}
 */
LoginManager.checkLogin = function(logincallback, unlogincallback, opt){
	// check reallogin report
	ATM.reportATM({
		toappid: 38,
		tomoduletype: 21,
		tointer: 11,
		toreturncode: 0,
		businesstype: comm.getGameId(),
		result: 0,
		cgi: location.href,
		errormsg: 'check login'
	});
	option = extend(option, opt);

	if (comm.isDouYuLoginStatus()) {
		cb.loginedCallback();
		if (isFunction(logincallback)) logincallback()
		return;
	}
	if (window.iUseQQConnect === 1 && !milo.cookie.get('acctype')) {
		cb.unloginCallback();
		if (isFunction(unlogincallback)) unlogincallback();
		return;
	}

	if (comm.checkUserLogined()  ){
		cb.loginedCallback();

		if (isFunction(logincallback) ){
			if ( !milo.cookie.get("wxcode")){
					var user=milo.unSerialize(comm.getIED_LOG_INFO())
					/*
						QQ互联登录态改造期间，临时允许pt与qc共存，【PT下线后删除改逻辑】 -----Start-----
					*/
					if('qc' == user.logtype && 1 != option.iUseQQConnect){
						user.logtype='pt';
						user.loginType='pt'
						user.openid='';
					}

					/*
						QQ互联登录态改造期间，临时允许pt与qc共存，【PT下线后删除改逻辑】 -----End-----
					*/
					//互联，wegame登录带上face
					if(/^(qc|wg|ks)$/.test(user.logtype) && comm.getUserFaceData(user.openid)){
						user.face=comm.getUserFaceData(user.openid);
					}
					logincallback(user);
			}else{

				LoginManager.wxRenderWhenLogined(logincallback);
			}
		}

	}else{

		var callbackName = 'jsonp' + milo.randomInt(100);
		comm.callbackLoginInfo(callbackName, function(IED_LOG_INFO2){
			var isLogin = comm.checkUserLogined();
			//_______isRunFirstMilo 代表是否正在请求登录cgi校验登录态，如果是，则将回调先缓存，如果不是，则请求远程cgi，并置为1
			//LoginManager._______isRunFirstMilo = 2;
			LoginManager._______isRunFirstMilo = 0;
			if(isLogin){
				cb.loginedCallback();
				if (isFunction(logincallback) ){
					if ( !milo.cookie.get("wxcode")){
							var user={
								"uin":comm.getUserUin(),
								"userUin":IED_LOG_INFO2.userUin,
								"nickname":comm.getNickName(),
								"nickName":IED_LOG_INFO2.nickName,
								"logtype":IED_LOG_INFO2.loginType || milo.cookie.get('acctype') || "qq",
								"loginType":IED_LOG_INFO2.loginType || milo.cookie.get('acctype') || "qq",
								'face':IED_LOG_INFO2.face || ''
							}
							if(/^(qc|wg|ks)$/.test(user.logtype)){
								user.openid=milo.cookie.get('openid') || '';
							}

							//头像缓存
							if(user.face && /^(qc|wg|ks)$/.test(user.logtype)){
								comm.storeUserFace(user.openid,user.face);
							}
							logincallback(user);
					}else{

						//LoginManager.wxRenderWhenLogined(logincallback,callbackName);
					}
				}

			}else{

				cb.unloginCallback();
				if (isFunction(unlogincallback)) unlogincallback();
			}

			while(true){
				if(LoginManager.logincallbackArray.length <= 0){
					break;
				}
				var temp = LoginManager.logincallbackArray.shift();
				temp(IED_LOG_INFO2);
			}
			LoginManager._______isRunFirstMilo = 0;
		});


		if(!LoginManager.logincallbackArray){
			LoginManager.logincallbackArray = [];
		}

		if(typeof(LoginManager._______isRunFirstMilo) == 'undefined'){
			LoginManager._______isRunFirstMilo = 0;
		}

		// _______isRunFirstMilo checklogin执行的状态表示，如果是0那么是第一次执行，如果不是0状态为正在执行

		if (LoginManager._______isRunFirstMilo != 0){
			LoginManager.logincallbackArray.push(window[callbackName]);
			return;
		}

		LoginManager._______isRunFirstMilo = 1;

		var acctype = requestLoginParam('acctype');
		//qc
		if(!acctype && 'qc'==milo.cookie.get('acctype')){
			acctype='qc';
		}
		//wegame
		if(!acctype && 'wg'==milo.cookie.get('acctype')){
			acctype='wg';
		}
		//ks
		if(!acctype && 'ks'==milo.cookie.get('acctype')){
			acctype='ks';
		}
		if(acctype == "weixin"){
			acctype = "wx";
		}
		var appid = requestLoginParam('appid');
		var openid = requestLoginParam('openid');

		var access_token = acctype=="wx"?requestLoginParam('access_token'):requestLoginParam('openkey');

		//add susahuang 支持页游openid、accesstoken传参方式
		if(location.host == "cfw.qq.com"){
			access_token = requestLoginParam('access_token');
		}
		//判断登录方式，如果是qc，则从cookie中取相关cookie
		if("qc" == acctype){
			appid=appid || milo.cookie.get('appid');
			openid=openid || milo.cookie.get('openid');
			access_token=access_token || milo.cookie.get('access_token');
			/*
				QQ互联登录态改造期间，临时允许pt与qc共存，【PT下线后删除改逻辑】 -----Start-----
			*/
			//如果本页面不走qc则，继续走pt
			if(option.iUseQQConnect != 1){
				appid='';
				openid='';
				access_token='';
				acctype='';
			}
			/*
				QQ互联登录态改造期间，临时允许pt与qc共存，【PT下线后删除改逻辑】 -----Start-----
			*/
		}
		//判断登录方式，如果是ks，则从cookie中取相关cookie
		if ("ks" == acctype) {
			appid = milo.cookie.get('appid');
			openid = milo.cookie.get('openid');
			access_token = milo.cookie.get('access_token');
		}
		//wegame 登录态
		if('wg'==acctype){
			appid=milo.cookie.get('appid') || '';
			access_token=milo.cookie.get('access_token') || '';
			openid=milo.cookie.get('openid') || '';
			//续期专用
			refresh_token=milo.cookie.get('refresh_token') || '';
			loadScriptLogin(comm.getCheckLoginUrl(option.gameId) + '?callback=' + callbackName + '&acctype=' + acctype + '&appid=' + appid + '&openid=' + openid + '&access_token=' + access_token+"&refresh_token="+refresh_token, function(loaded){
			});
		}else if(acctype){
			loadScriptLogin(comm.getCheckLoginUrl(option.gameId) + '?callback=' + callbackName + '&acctype=' + acctype + '&appid=' + appid + '&openid=' + openid + '&access_token=' + access_token+"&game="+comm.getGameId(), function(loaded){
			});
		}else{
			//如果是微信扫码登陆，则先进行codeToOpenId动作
			var wxcode = requestLoginParam('code');
			if (wxcode && !milo.cookie.get("openid") ){

				//执行微信的code转openID
				LoginManager.doWxCodeToOpenId(wxcode,function(openidInfo){
					var originalUrl= decodeURIComponent(requestLoginParam('originalUrl'));
					//openid拿到后，先做一次跳转，去掉URL上的code，appid等传值
					/*if(location.protocol == "https:"){
						window.top.location.href=originalUrl;
					}else{
						document.location.href=originalUrl;
					}*/
					//新的回调方式
					if(isFunction(parent.milo_WxLoginCallback)){
						parent.milo_WxLoginCallback();
					}else{
						//老的方式，跳转
						if(milo.xss.isSafeUrl(originalUrl)){
							document.location.href=originalUrl;
						}
					}
				});


			}else if (milo.cookie.get("wxcode")){
				//有微信code，说明已经微信登录了，直接走wxRenderWhenLogined,_______isRunFirstMilo置为0，不走callback  缓存了。
				LoginManager._______isRunFirstMilo=0;
				LoginManager.wxRenderWhenLogined(logincallback);
			}else{
				//调用后端接口，通过和_______isRunFirstMilo结合，使用callback 缓存控制，使所有回调生效，同时避免多次调用后端接口
				loadScriptLogin(comm.getCheckLoginUrl(option.gameId) + '?callback=' + callbackName+"&game="+comm.getGameId(), function(loaded){});
			}
		}
	}
};

/**
 * 发请求强校验否登陆，并执行对应回调
 * @param {function} logincallback 已登陆的回调
 * @param {function} unlogincallback 未登陆的回调
 * @param {object} opt 登陆配置项
 * @return {undefined}
 */
LoginManager.checkRealLogin = function(logincallback, unlogincallback, opt){
	// check reallogin report
	ATM.reportATM({
		toappid: 38,
		tomoduletype: 21,
		tointer: 12,
		toreturncode: 0,
		businesstype: comm.getGameId(),
		result: 0,
		cgi: location.href,
		errormsg: 'checkReal login'
	});
	option = extend(option, opt);
	var callbackName = 'jsonp' + milo.randomInt(100);
	comm.callbackLoginInfo(callbackName, function(IED_LOG_INFO2){
		var isLogin = comm.checkUserLogined();
		//_______isRunFirstMilo 代表是否正在请求登录cgi校验登录态，如果是，则将回调先缓存，如果不是，则请求远程cgi，并置为1
		LoginManager._______isRunFirstMilo = 0;
		if(isLogin){
			cb.loginedCallback();
			if (isFunction(logincallback)){
				if (!milo.cookie.get("wxcode")) {
					var user = {
						uin: comm.getUserUin(),
						userUin: comm.getUserUin(),
						nickName: IED_LOG_INFO2.nickName,
						nickname: comm.getNickName(),
						logtype: IED_LOG_INFO2.loginType || milo.cookie.get('acctype') || "qq",
						loginType: IED_LOG_INFO2.loginType || milo.cookie.get('acctype') || "qq",
						face: IED_LOG_INFO2.face || ''
					}
					if(/^(qc|wg|ks)$/.test(user.logtype)){
						user.openid=milo.cookie.get('openid') || '';
						//头像缓存
						if(user.face){
							comm.storeUserFace(user.openid,user.face);
						}
					}
					logincallback(user);
				} else {
					LoginManager.wxRenderWhenLogined(logincallback,callbackName);
				}
			}

		}else{
			cb.unloginCallback();
			if (isFunction(unlogincallback)) {
				unlogincallback();
			}
		}

		while(LoginManager.logincallbackArray.length) {
			var loginCb = LoginManager.logincallbackArray.shift();
			loginCb(IED_LOG_INFO2);
		}

	});

	if(!LoginManager.logincallbackArray){
		LoginManager.logincallbackArray = [];
	}

	// _______isRunFirstMilo checklogin执行的状态表示，如果是0或undefined那么是第一次执行，如果是1状态为正在执行,则把回调函数入栈
	if (LoginManager._______isRunFirstMilo == 1){
		LoginManager.logincallbackArray.push(window[callbackName]);
		return;
	}

	LoginManager._______isRunFirstMilo = 1;

	var acctype = requestLoginParam('acctype') || milo.cookie.get('acctype');
	if(acctype == "weixin") {
		acctype = "wx";
	}
	var access_token = (acctype == "wx" || location.host == "cfw.qq.com") ? //支持页游openid、accesstoken传参方式
		requestLoginParam('access_token') : requestLoginParam('openkey');
	access_token = access_token || milo.cookie.get('access_token') || '';

	var urlParams = {
		callback: callbackName,
		acctype: acctype,
		appid: requestLoginParam('appid') || milo.cookie.get('appid') || '',
		openid: requestLoginParam('openid') || milo.cookie.get('openid') || '',
		access_token: access_token,
		game: comm.getGameId()
	}

	if (acctype) {
		if ('qc' == acctype) {
			/*
				QQ互联登录态改造期间，临时允许pt与qc共存，【PT下线后删除改逻辑】 -----Start-----
			*/
			//如果本页面不走qc则，继续走pt
			if(option.iUseQQConnect != 1){
				extend(urlParams, {
					appid: '',
					openid: '',
					access_token: '',
					acctype: ''
				})
			}
		}
		//wegame 登录态
		if('wg' == acctype || 'ks' == acctype) {
			params.appid = milo.cookie.get('appid') || '';
			params.openid = milo.cookie.get('openid') || '';
			params.access_token = milo.cookie.get('access_token') || '';
			//续期专用
			params.refresh_token=milo.cookie.get('refresh_token') || '';
		}
		loadScriptLogin(comm.getCheckLoginUrl(option.gameId) + comm.buildParams(urlParams), function(loaded){
		});
	} else {
		//如果是微信扫码登陆，则先进行codeToOpenId动作
		var wxcode = requestLoginParam('code');
		if (wxcode && !milo.cookie.get("openid") ){

			//执行微信的code转openID
			LoginManager.doWxCodeToOpenId(wxcode,function(openidInfo){
				var originalUrl= decodeURIComponent(requestLoginParam('originalUrl'));
				//新的回调方式
				if(isFunction(parent.milo_WxLoginCallback)){
					parent.milo_WxLoginCallback();
				}else{
					//老的方式，跳转
					if(milo.xss.isSafeUrl(originalUrl)){
						document.location.href=originalUrl;
					}
				}
			});
		} else {
			//调用后端接口，通过和_______isRunFirstMilo结合，使用callback 缓存控制，使所有回调生效，同时避免多次调用后端接口
			loadScriptLogin(comm.getCheckLoginUrl(option.gameId) + '?callback=' + callbackName+"&game="+comm.getGameId(), function(loaded){});
		}
	}
};

//如果微信登陆了，就执行微信的登陆成功获取用户信息的回调
LoginManager.wxRenderWhenLogined=function(logincallback){
	var openId=milo.cookie.get("openid");
	var access_token=milo.cookie.get("access_token");
	LoginManager.getUserInfoByWxOpenId({"openid":openId,
									"access_token":access_token},function(wxUserInfo){
										if (isFunction(logincallback) && wxUserInfo)	{
											wxUserInfo.logtype="wx";
											wxUserInfo.loginType="wx";
											LoginManager.wxUserInfo=wxUserInfo;

											if (isDom(g(option.loginedDiv))){
												g(option.loginedDiv).style.display = "block";
											}
											if (isDom(g(option.unloginDiv))){
												g(option.unloginDiv).style.display = "none";
