//getUserInfo请求队列机制
/*
	当同一时段内有多个请求同时发出时，则缓存除第一个请求之外的其它请求，
	等第一个请求有响应的时候再遍历其它请求的回调函数直接执行

*/
LoginManager.wxUserInfoRequestQueue={
	//队列数据
	//格式：
	/*
		{
			"openid1_token1":[cb1,cb2,cb3],
			"openid2_token2":[cb1,cb2,cb3],
		}
	*/
	queueList:{

	},
	//指定请求是否有在等待
	isWaiting:function(openid,access_token,lang){
		var k=openid+'_'+access_token+'_'+lang;
		return (this.queueList[k] && this.queueList[k].length);
	},
	//添加请求到队列
	add:function(openid,access_token,lang,callback,errCallback){
		var k=openid+'_'+access_token+'_'+lang;
		if(!this.queueList[k]){
			this.queueList[k]=[{
				success:callback,
				fail:errCallback
			}];
		}else{
			this.queueList[k].push({
				success:callback,
				fail:errCallback
			});
		}
	},
	//执行队列
	run:function(openid,access_token,lang,wxUserData){
		var cbArr=this.queueList[openid+'_'+access_token+'_'+lang];
		while(cbArr && cbArr.length){
			var cbObj=cbArr.shift();
			//成功回调
			if(0 == wxUserData.iRet && isFunction(cbObj.success)){
				cbObj.success(wxUserData.data);
			}else if(0 !== wxUserData.iRet && isFunction(cbObj.fail)){//失败回调
				cbObj.fail(wxUserData);
			}
		}
	}
};
