/**
 * 取得用户呢称(支持qc/pt/wg/qc/ks登录方式)
 * @param {function} callback 方法调用后的回调，异步返回用户的昵称
 * @return {string} nickName 同步返回用户的昵称
 */
LoginManager.getNickName = function(callback){
	//异步方式
	LoginManager.checkLogin(function(){
		//登录成功
		var nickName = comm.getNickName();
		isFunction(callback) && callback({
				isLogin:true,
				nickName:nickName
		});
	},function(){
		//登录失败
		isFunction(callback) && callback({
			isLogin:false,
			nickName:''
		});
	})
	//支持同步方式
	return comm.getNickName();
};

/**
 * 取得用户的会员信息
 * @param {string} gameId 所属业务id 目前可查询有cf,xx,ava,roco,qq
 * @param {function} callback 获取后的回调
 * @return {undefined}
 */
LoginManager.getUserVip = function(gameId, callback){
	gameId = gameId || '';
	gameId = gameId.toLowerCase();
	var VIPMAP = {
		'cf' : true,
		'xx' : true,
		'ava' : true,
		'roco' : true,
		'qq' : true //qq会员
	};
	if(gameId && VIPMAP[gameId]){
		need("util.uservip",function(Vip){
			LoginManager.checkLogin(function(){
				Vip['get' + gameId.toUpperCase() + 'Vip'](callback);
			}, function(){
				//如果未登录就不用查询了
				var vip_obj = Vip.getVIPObj();
				if(typeof(callback) == 'function'){
					callback(vip_obj);
				}
			});
		});
	}
};

/**
