/**
 * 验证用户是否登陆并执行回调
 * @param {function} callback 登陆后的调用
 * @return {undefined}
 */
LoginManager.submitLogin = function(callback){
	if (!isFunction(callback)) {callback = function(){};}
	LoginManager.checkLogin(function(){
		callback();
	}, function(){
		LoginManager.login(function(){
			cb.loginedCallback();
			callback();
		});
	});
};

/**
 * 验证用户是否登陆并提交
 * @param {function} callback 已登陆的回调
 * @param {function} callback 未登陆时要求用户登陆并回调此方法，如无则默认刷新页面
 * @return {undefined}
 */
LoginManager.reloadLogin = function(callback, unLoginCallback){
	if (!isFunction(callback)) {callback = function(){};}
	if (!isFunction(unLoginCallback)) {
		unLoginCallback = function(){
			location.reload();
		};
	}
	LoginManager.checkLogin(function(){
		callback();
	}, function(){
		LoginManager.login(function(){
			unLoginCallback();
		});
	});
};

/**
 * 登陆页打开后的方法，专门用于iframe框调整高宽进行
 * @private
 */
function ptlogin2_onResize(width, height){
	var login_wnd = logWin.getLoginDiv();
	if (login_wnd){
		login_wnd.style.width = width + "px";
		login_wnd.style.height = height + "px";

		login_wnd.style.visibility = "hidden";
		login_wnd.style.visibility = "visible";
	}
}

/**
 * 登录框关闭的回调方法
 * loginmanagerv3 和login同时存在,登录后关闭层的兼容判断处理
 * @private
 */
try{
	if(ptlogin2_onClose_v3 && isFunction(ptlogin2_onClose_v3) && g('_overlay_') && g('_overlay_').style.display != 'block'){
		var ptlogin2_onClose = ptlogin2_onClose_v3;
		Dialog.hide();
	}else{
		var ptlogin2_onClose = function(){
			Dialog.hide();
		}
	}
}catch(e){
	var ptlogin2_onClose = function(){
		Dialog.hide();
	}
}



window["ptlogin2_onClose"] = ptlogin2_onClose;
window["ptlogin2_onResize"] = ptlogin2_onResize;


if (typeof window.postMessage !== 'undefined') {
	window.onmessage = function(event) {
		var msg = event || window.event; // 兼容IE8
		if(msg.origin == 'https://xui.ptlogin2.qq.com'){
			var data;
			if (typeof  JSON !== 'undefined') // IE7兼容模式不存在JSON对象
				data = JSON.parse(msg.data);
			else
				data = str2JSON(msg.data);

			switch (data.action) {
				case 'close':
				ptlogin2_onClose();
				break;

				case 'resize':
				ptlogin2_onResize(data.width, data.height);
				break;

				default: //什么也不做，便于我们扩展接口
				break;
			}
		}
		// 考虑到ptlogin接口的扩展性，希望业务在对于data.action的条件处理也要保持一定的可扩展性
		// 如不要采用：data.action == 'resize' ? ptlogin2_onResize(data.width, data.height) : ptlogin2_onClose()
		// 一旦ptlogin支持了新的接口，那么该代码将会无法正常工作，影响业务正常使用
	}
}

/**
 * [str2JSON 降字符串转换成json对象（供业务参考）]
 * @param  {[type]} str [description]
 * @return {[type]}     [description]
 */
function str2JSON(str) {
	eval('var __pt_json='+str);
	return __pt_json;
}

/**
 * 登陆初始化参数
 * @param {object} opt 初始化配置项
 * @return {undefined}
 */
LoginManager.init = function(opt){
	option = extend(option, opt);
	//改造期间方便全局识别，兼容pt和qc共存
	if(1 == option.iUseQQConnect){
		window.iUseQQConnect=1;
	}
	option.gameId = (!isObject(opt) || !opt.gameId) ? comm.getGameId() : opt.gameId;
	option.appId = (!option.appId) ? comm.getAppId(option.gameId) : option.appId;

	if (comm.checkUserLogined()){
		cb.loginedCallback();
	}
	else{
		cb.unloginCallback();
	}
};

LoginManager.init();
return LoginManager;
