          var deps = queue.splice(startPos, 1).pop();
          //console.log("######################");
          //console.log(name);
          //console.log(queue);
          //console.log(modulemap);
          if (deps == null) {
            milo.loader.modulemap[name] = ret;
            return;
          }

          //**如deps名字与name名字不一致时。。。那么。。。那么。。
          //if (deps[0] == null){
