 * 本类中所有方法被绑定到milo对象中，通过对milo.方法名进行调用。<br/>
 * <p>
 * Example:
 * <pre><code>
milo.addEvent(g('getString'),'click',function(e){
	alert(isString(g('string').value))
})
 *</code></pre>
 * </p>
 */

namespace("milo.event");

(function () {
  var event = milo.event;
  extend(event, {
    /**
     * 为DOM对象增加事件
     * @param {dom} element dom对象
     * @param {string} type 事件名称
     * @param {function} type 事件方法
     * @return {undefined}
     */
    addEvent: function (el, type, fn) {
      if (window.addEventListener) {
        el.addEventListener(type, fn, false);
      } else {
        el["on" + type] = fn;
      }
    },
    /**
     * 为DOM对象移除事件
     * @param {dom} element dom对象
     * @param {string} type 事件名称
     * @param {function} type 事件方法
     * @return {undefined}
     */
    removeEvent: function (el, type, fn) {
      if (window.removeEventListener) {
        el.removeEventListener(type, fn, false);
      } else {
        el["on" + type] = null;
      }
    },
    isReady: false,
    readyFn: [],
    /**
     * dom ready事件
     * @param {dom} element dom对象
     * @param {string} type 事件名称
     * @param {function} type 事件方法
     * @return {undefined}
     */
    ready: function (fn) {
      bindReadyEvent();
      if (milo.isReady) {
        fn.call();
      } else {
        if (isFunction(fn)) {
          milo.readyFn.push(fn);
        }
      }
    },

    /**
     * 该方法用于绑定点击事件，比一般的click事件反应速度快2倍。
     * @param {dom} obj 要绑定的dom对象
     * @param {function} fun 事件触发的函数
     *  @return {undefined}
     */
    touchClick: function (obj, fun) {
      var start_x = 0,
        start_y = 0;
      obj.addEventListener("touchstart", function (e) {
        start_x = e.touches[0].clientX;
        start_y = e.touches[0].clientY;
        document.addEventListener("touchend", touEnd, false);
      });
      function touEnd(e) {
        var endX = e.changedTouches[0].clientX;
        var endY = e.changedTouches[0].clientY;
        if (Math.abs(endX - start_x) < 5 && Math.abs(endY - start_y) < 5) {
          fun.call(obj, e);
        }
        document.removeEventListener("touchend", touEnd, false);
      }
    },
    /**
     * 停止事件继续进行
     * @param {event} e 事件
     * @return {dom}
     */
    preventDefault: function (e) {
      if (e.preventDefault) {
        e.preventDefault();
      } else {
        e.returnValue = false;
      }
    },
    /**
     * 阻止事件冒泡传递
     * @param {event} e 事件
     * @return {dom}
     */
    stopPropagation: function (e) {
      if (e.stopPropagation) {
        e.stopPropagation();
      } else {
        e.cancelBubble = true;
      }
    },
  });

  function bindReadyEvent() {
    if (document.readyState === "complete") {
      return ready();
    }
    if (document.addEventListener) {
      document.addEventListener(
        "DOMContentLoaded",
        function () {
          document.removeEventListener(
            "DOMContentLoaded",
            arguments.callee,
            false
          );
          ready();
        },
        false
      );
      window.addEventListener("load", ready, false);
    }
  }

  function ready() {
    if (!milo.isReady) {
      if (!document.body) {
        return setTimeout(ready, 13);
      }

      milo.isReady = true;
      //把预加载的合并文件里的Define，进行预Need一下,以利用原逻辑，加到map中 add by dickma
      milo.loader.preNeed();

      //在Dom加载完毕后，如果milo.ready()里有回调方法，则进行执行
      if (milo.readyFn.length > 0) {
        var i = 0,
          fn;

        while ((fn = milo.readyFn[i++])) {
          fn.call();
        }

        milo.readyFn.length = 0;
      }
    }
  }
})();
