	//判断是否安全
	isLegalDomain:function(domain,jumpUrl,needReport){
		//判断的过程中是否要上报
		if('boolean' != typeof needReport){
			needReport=true;
		}
		var self=this;
		//先判断是否在safeDomainList中，决定是否上报
		var isSafe=false;
		for(var i=0;i<self.safeDomainList.length;i++){
			var sSafeDomain=self.safeDomainList[i];
			if(sSafeDomain == domain){
				isSafe=true;
				break;
			}
			var index=0;
			if((index=domain.indexOf(sSafeDomain))>0){
				if(domain.length == (sSafeDomain.length + index)){
					if('.' == domain.substr(index-1,1)){
						isSafe=true;
						break;
					}
				}
			}
		}
		var isBlack=false;
		//黑名单中的也安全
		for(var l=0;l<self.blackDomain.length;l++){
			var sBlackSafe=self.blackDomain[l];
			if(sBlackSafe == domain){
				isBlack=true;
				break;
			}
			var index=0;
			if((index=domain.indexOf(sBlackSafe))>0){
				if(domain.length == (sBlackSafe.length + index)){
					if('.' == domain.substr(index-1,1)){
						isBlack=true;
						break;
					}
				}
			}
		}
		//上报
		if(!self.hasReport[domain] && needReport){
			self.hasReport[domain]=true;
			if(isBlack){
				//黑名单
				self.reportATM(jumpUrl,domain,-1);
			}else if(!isSafe){
				//可疑
				self.reportATM(jumpUrl,domain,1);
			}else{
				//放行
				self.reportATM(jumpUrl,domain,0);
			}
		}

		//再判断是否可以跳转
		//---白名单
		var isLegal=false;
		for(var j=0;j<self.whiteDomain.length;j++){
			var sWhiteDomain=self.whiteDomain[j];
			if(sWhiteDomain == domain){
				isLegal=true;
				break;
			}
			var index=0;
			if((index=domain.indexOf(sWhiteDomain))>0){
				if(domain.length == (sWhiteDomain.length + index)){
					if('.' == domain.substr(index-1,1)){
						isLegal=true;
						break;
					}
				}
			}
		}
		//黑名单
		for(var k=0;k<self.blackDomain.length;k++){
			var sBlackDomain=self.blackDomain[k];
			if(sBlackDomain == domain){
				isLegal=false;
				break;
			}
			var index=0;
			if((index=domain.indexOf(sBlackDomain))>0){
				if(domain.length == (sBlackDomain.length + index)){
					if('.' == domain.substr(index-1,1)){
						isLegal=false;
						break;
					}
				}
			}
		}
		return isLegal;
	},
	//判断是否可疑链接(链接中包括外部域名关键词和黑名单关键词) [判断所有可以解包的层]
	isSuspectUrl:function(url){
		var self=this;
		if(!url){
			return false;
		}
		var finalUrl=url;
		//一层一层decode，针对多层跳转
		try{
			while(finalUrl != decodeURIComponent(finalUrl)){
				finalUrl=decodeURIComponent(finalUrl);
			}
		}catch(e){

		}
		var reg=new RegExp('https?\\:\\/\\/(([\\w\\-\\_]+\\.)+\\w+)','i');
		var arrDomainList=[];
		while (finalUrl && reg.test(finalUrl)) {
			var pattern=finalUrl.match(reg);
			finalUrl=finalUrl.substring(pattern.index+pattern[0].length,finalUrl.length);
			arrDomainList.push(pattern[1]);
			if(!self.isLegalDomain(pattern[1],'',false)){
				return true;
			}
		}
		return false;//非可疑
	},
	//只判断第一层
	isLegalUrl:function(jumpUrl){
		var self=this;
		try{
			if(jumpUrl){
				var match=jumpUrl.match(/^(https\:\/\/|http\:\/\/|\/\/|)(([\w\-]+\.)+[\w\-]+)(\:[0-9]*){0,1}((\/|\?|\#).*){0,1}$/);
				if(match && match[2]){
					var domain=match[2];
					return self.isLegalDomain(domain,jumpUrl,false);
				}
			}
		}catch(e){

		}
		return true;
	},
	filterXSS:function(oriStr,isNotStrict){
		if(!oriStr){
			return oriStr;
		}
		var charCodes=['3c','3e','27','22','28','29','60',{format:'script{}',chr:'3a'}];//要转义字符的16进制ASCII码[1<  2>  3'  4"  5(  6)  7`]
		var xssChars=[],filterChars=[],tmpFormat='{}',tmpChr;
		for(var i=0;i<charCodes.length;i++){
			if('string'==typeof charCodes[i]){
				tmpFormat='{}';
				tmpChr=charCodes[i];
			}else{
				tmpFormat=charCodes[i].format;
				tmpChr=charCodes[i].chr
			}
			xssChars.push(tmpFormat.replace('{}','\\u00'+tmpChr));
			if(!isNotStrict){
				xssChars.push(tmpFormat.replace('{}','%'+tmpChr));//1次encode
				xssChars.push(tmpFormat.replace('{}','%25'+tmpChr));//2次encode
			}

			filterChars.push(tmpFormat.replace('{}','&#x'+tmpChr+';'));
			if(!isNotStrict){
				filterChars.push(tmpFormat.replace('{}','%26%23x'+tmpChr+'%3B'));//1次encode
				filterChars.push(tmpFormat.replace('{}','%2526%2523x' + tmpChr + '%253B'));//2次encode
			}

		}
		for(var i=0;i<xssChars.length;i++){
			oriStr=oriStr.replace(new RegExp(xssChars[i],'gi'),filterChars[i]);
		}
		//预防script:
		oriStr=oriStr.replace(/script[\u000d\u000a\u0020]+\:/,'script&#x3a;');
		return oriStr;
	},
	//跳转，只检查第一层
	jump:function(jumpUrl,target){
		target=target || window;//默认self跳转
		var self=this;
		try{
			if(jumpUrl){
				var match=jumpUrl.match(/^(https\:\/\/|http\:\/\/|\/\/|)(([\w\-]+\.)+[\w\-]+)(\:[0-9]*){0,1}((\/|\?|\#).*){0,1}$/);
				if(match && match[2]){
					var domain=match[2];
					if(self.isLegalDomain(domain,jumpUrl)){
						if(self.isSuspectUrl(jumpUrl)){
							//全路径可拆分多域名有可疑
							//上报可疑
							self.reportSuspect(jumpUrl,true);
							target.location.href=self.filterXSS(jumpUrl);
						}else{
							self.reportSuspect(jumpUrl,false);
							//宽松跳转模式，不校验encode参数
							target.location.href=self.filterXSS(jumpUrl,true);
						}

					}
				}
			}
		}catch(e){

		}
	},
	//严格跳转，检查所有层
	strictJump:function(jumpUrl,target){
		target=target || window;//默认self跳转
		var self=this;
		try{
			if(jumpUrl){
				var match=jumpUrl.match(/^(https\:\/\/|http\:\/\/|\/\/|)(([\w\-]+\.)+[\w\-]+)(\:[0-9]*){0,1}((\/|\?|\#).*){0,1}$/);
				if(match && match[2]){
					var domain=match[2];
					if(self.isLegalDomain(domain,jumpUrl)){
						if(self.isSuspectUrl(jumpUrl)){
							//全路径可拆分多域名有可疑
							//上报可疑并且不跳转
							self.reportSuspect(jumpUrl,true);
						}else{
							//无可疑
							target.location.href=self.filterXSS(jumpUrl);
							self.reportSuspect(jumpUrl,false);
						}
					}
				}
			}
		}catch(e){

		}
	},
	//上报可疑和非可疑跳转
	reportSuspect:function(jumpUrl,isSuspect){
		var url=location.href;
		var index1=url.indexOf('?');
		if(index1>=0){
			url=url.substring(0,index1-1);
		}
		var index2=url.indexOf('#');
		if(index2>=0){
			url=url.substring(0,index2-1);
		}
		var msg="跳转正常";
		if(isSuspect){
			msg='跳转可疑:['+jumpUrl+']';
		}
		var reportData={
			cgi:url,
			errormsg:msg,
			fromappid:38,
			frommoduletype:1,
			serialtime:parseInt(new Date().getTime()/1000),
			struserid:"",
			toappid:1,
			tomoduletype:166,//前端模块
			tointer:5,//上报跳转可疑情况
			result:isSuspect?1:0,
			toreturncode:0
		}
		this.postATM(reportData, this.api.atmUrl, function(res){
			/*if(typeof callback == "function"){
				callback(res);
			}*/
		},3000);
	},
	//上报使用情况
	reportUsage:function(){
		var url=location.href;
		var index1=url.indexOf('?');
		if(index1>=0){
			url=url.substring(0,index1-1);
		}
		var index2=url.indexOf('#');
		if(index2>=0){
			url=url.substring(0,index2-1);
		}

		var reportData={
			cgi:url,
			errormsg:"页面地址:["+url+"]",
			fromappid:38,
			frommoduletype:1,
			serialtime:parseInt(new Date().getTime()/1000),
			struserid:"",
			toappid:1,
			tomoduletype:166,//前端模块
			tointer:4,//loginSuccess.html使用情况
			result:1,
			toreturncode:0
		}
		this.postATM(reportData, this.api.atmUrl, function(res){
			/*if(typeof callback == "function"){
				callback(res);
			}*/
		},3000);
	},
	//如果非白名单则上报ATM
	reportATM:function(url,domain,type){
		/*
			type=0  白名单放行
			type=1  嫌疑
			type=-1 黑名单
		*/
		var msg='';
		if(0 == type){
			msg='白名单地址:['+url+']';
		}else if(-1 == type){
			msg='黑名单地址:['+url+']';
		}else{
			msg='可以跳转地址:['+url+']';
		}

		var referrer=document.referrer || '';
		var currentPage=location.href;
		if(currentPage.indexOf('?')>0){
			currentPage=currentPage.substring(0,currentPage.indexOf('?')-1);
		}
		if(currentPage.indexOf('#')>0){
			currentPage=currentPage.substring(0,currentPage.indexOf('#')-1);
		}
		msg='来源:['+referrer+']'+'本页:['+currentPage+']'+msg;
		var reportData={
			cgi:domain,
			actid:domain,
			errormsg:msg,
			fromappid:38,
			frommoduletype:1,
			serialtime:parseInt(new Date().getTime()/1000),
			struserid:"",
			toappid:1,
			tomoduletype:166,//前端模块
			tointer:3,//前端安全跳转监控
			result:type,
			toreturncode:0
		}
		this.postATM(reportData, this.api.atmUrl, function(res){
			/*if(typeof callback == "function"){
				callback(res);
			}*/
		},3000);
	},
	//发起请求，兼容IE低版本浏览器
	postATM:function(data,url,callback,outTime){
		//IE浏览器单独处理
		if(/MSIE/.test(navigator.userAgent)){
			this.postATMForIE(data,url,callback,outTime);
			return;
		}
		try{
			var timeout; //用来作超时处理

			var xmlhttp;
			if (window.XMLHttpRequest){
				xmlhttp=new XMLHttpRequest();
			}else{
				xmlhttp=new ActiveXObject("Microsoft.XMLHTTP");
			}
			xmlhttp.onreadystatechange=function(){
				if (xmlhttp.readyState==4 && xmlhttp.status==200){
					if(typeof callback == "function"){
						//成功则清除超时设置
						if(timeout){
							clearTimeout(timeout);
						}
						callback(xmlhttp.responseText);
					}
				}
			}
			xmlhttp.open("post",url,true);
			xmlhttp.send(JSON.stringify(data));

			//超时设置
			timeout = setTimeout(function(){
				if (xmlhttp) xmlhttp.abort();
			}, outTime);
		}catch(e){

		}
	},
	//IE下请求ATM，通过中转页面，防止安全提示
	postATMForIE:function(data, url, callback, outTime){
		var self=this;
		var pAIFrame=null;
		if(!document.getElementById("postATMFrame")){
			pAIFrame = document.createElement("iframe");
			pAIFrame.id = "postATMFrame";
			pAIFrame.name = "postATMFrame";
			pAIFrame.scrolling="no";
			pAIFrame.frameBorder ="0";
			pAIFrame.style.width="0px";
			pAIFrame.style.overflow="hidden";
			pAIFrame.style.display ="none";
			pAIFrame.style.position="absolute";
			document.body.appendChild(pAIFrame);
		}else{
			pAIFrame=document.getElementById("postATMFrame");
		}
		//延迟发送时间，排队，防止请求被canceled
		//假设每一个请求需要2000ms
		var delayTime=parseInt(pAIFrame.getAttribute("data-delay") || 0);//delayTime标识下一个可以发送请求的时间点（用时间戳表示）
		var delayRequest=0;//下一个可以发送请求的时间点相对于当前时间的diff
		//请求ATM动作
		var requestFunc=function(){
			var postATMUrl=self.api.crossDomainUrl;//中转页面
			postATMUrl+="?_t=" + parseInt((Math.random()*100000)) + "&url="+encodeURIComponent(url)+"&data="+encodeURIComponent(JSON.stringify(data))+"&timeout="+ (outTime||0);
			pAIFrame.src=postATMUrl;
		}
		//如果有延迟时间并且延迟时间在当前时间之后，则延迟上报
		if(delayTime && delayTime>new Date().getTime()){
			delayTime+=2000;
			delayRequest=(delayTime-new Date().getTime());
			setTimeout(function(){
				requestFunc();
			},delayRequest)
		}else{//否则立即上报
			requestFunc();
			delayTime=new Date().getTime()+2000;
		}
		pAIFrame.setAttribute("data-delay",delayTime);
	}
}

/*
Milo前端监控(基于Aegis)
*/
(function(){

  //内部成员变量-业务相关
  var isInitOK=false;
  var isLoadingAegis=false;//是否正在加载中
  var isLoadingTdm=false;
  var loadAegisCb=[];
  var loadTdmCb=[];
  var oCurrentConfig=null;
  var oExtraParams={};
  var aegisInstanse=null;
  var isTdmLoad=false;

  //内部成员变量-milojs相关
  var isInitMiloOK=false;
  var aegisInstanseForMilo=null;
  var arrInitMiloCb=[];
  var loadMiloStatus=0;

  //获取当前域名对应的配置信息
  /*
    {
      'lol.qq.com':{
          sMiloAegisId:'',//表示milo自身的监控，需要分散到域名
          sHash:''//sHash如果是空，则表示没有业务监控，如果非空，表示有业务监控，可用来做缓存
      }
    }
    */
  var arrGetDomainListCb=[];
  var oDomainConfig=null;
  var iDomainConfigStatus=0;//0 not load. 1 pending. 2 loaded ok or fail

  //fBeforeAegisReport
  //beforeReport 触发的时候统一要执行的函数
  var fBeforeAegisReport = function(log,isMilo){
      var uin=frontmonitor.getUin();
      //上报Tdm
      if(isTdmLoad && oCurrentConfig.sTdmId){
          window.TDM.reportEvents({
            events: [{
                srcId: 15002,
                eventName: "ErrorLog",
                eventInfo: {
                  s_from: location.href,
                  s_uin: uin,
                  s_itemId: oCurrentConfig.sAegisId,
                  s_errlevel:log.level,
                  s_errcontent: log.msg
                }
            }],
            success:function(result){
                console.info(result);
            },
            error:function(errMessage){
                console.error(errMessage);
            }
        });
       }
  }

  var getDomainListConfig=function(callback){
    if(2 == iDomainConfigStatus){
       isFunction(callback) && callback(oDomainConfig);
       return;
    }
    arrGetDomainListCb.push(callback);
    if(1 == iDomainConfigStatus){
      return;
    }
    iDomainConfigStatus=1;
    milo.loadScript('//ossweb-img.qq.com/images/js/milo_config_server/milo_monitor_alldomain.js',function(isLoad){
        iDomainConfigStatus=2;
        if(false !== isLoad){
          oDomainConfig=(window['Milo_Monitor_All_Domain'] && window['Milo_Monitor_All_Domain'][location.host])|| null;
        }
        while(arrGetDomainListCb.length){
          var tmpCb=arrGetDomainListCb.shift();
          isFunction(tmpCb) && tmpCb(oDomainConfig);
        }
    });
  }


  //获取当前页面匹配到的监控配置文件
  var getMonitorConfig=function(callback){
      if(oCurrentConfig){
        callback(oCurrentConfig);
        return;
      }
        getDomainListConfig(function(oDomainConfig){
            //如果该域名下只有milo自身监控，则不加载domainlist
            if(oDomainConfig && 1 != oDomainConfig.isOnlyMilo){
              milo.loadScript('//ossweb-img.qq.com/images/js/milo_config_server/milo_monitor_web_'+ location.host +'.js',function(isLoad){
                if(false === isLoad){
                  callback(null);
                }else{
                  var hostConfig=window.Milo_Monitor_Config;
                  if(hostConfig){
                    var currentHash=hostConfig.hash;
                    var arrConfig=hostConfig.data;
                    if(isArray(arrConfig)){
                      var currentUrl=location.href.substring(7);
                      var currentConfig=null;
                      if('https:' == location.protocol){
                        currentUrl=location.href.substring(8);
                      }
                      for(var i=0;i<arrConfig.length;i++){
                        if(!arrConfig[i].isOnline){
                          continue;
                        }
                        var sUrl=arrConfig[i].url;
                        if(currentUrl.length >= sUrl.length && 0 == currentUrl.indexOf(sUrl)){
                          currentConfig=arrConfig[i];
                          break;
                        }
                        //配置的是域名
                        if(sUrl == location.host){
                          currentConfig=arrConfig[i];
                          break;
                        }
                        //配置的是父域名
                        if(new RegExp('^([\\w\\-]+\\.)+'+sUrl+'$').test(location.host)){
                          currentConfig=arrConfig[i];
                          break;
                        }
                      }
                      oCurrentConfig=currentConfig;
                      callback(currentConfig);
                    }else{
                      callback(null);
                    }
                  }
                }
              })
            }else{
              callback(null);
            }
        });
  }

  //isLogAboutMilo 判断该条日志是否是milojs逻辑相关
  var isLogAboutMilo=function(log){
    var msg=log.msg || '';
    var isAbout=false;
    var arrAboutReg=[
      /((ossweb\-img\.qq\.com)|(game\.gtimg\.cn))\/images\/js\/(milo|(milo\_bundle)|mobile|(mobile\_bundle)|(mobile\_build))/ig
    ];
    var arrNotAboutReg=[
      /(ossweb\-img\.qq\.com|game\.gtimg\.cn)\/images\/js\/(milo|milo\_bundle|mobile|mobile\_bundle|mobile\_build)\/util\/(jquery|zepto)\.js/ig
    ];
    //先过滤掉黑名单影响
    for(var j=0;j<arrNotAboutReg.length;j++){
      msg=msg.replace(arrNotAboutReg[j],'');
    }
    //白名单
    for(var i=0;i<arrAboutReg.length;i++){
      if(arrAboutReg[i].test(msg)){
        isAbout=true;
        break;
      }
    }

    return isAbout;
  }

  var frontmonitor={
    init:function(callback,extraParams){
      var self=this;
      this.initForMilo();
      if(isInitOK){
        isFunction(callback) && callback({
          oAegis:aegisInstanse,
          oTdm:window.tdm
        });
        return;
      }
      oExtraParams=extraParams || {aegis:null,tdm:null};
      getMonitorConfig(function(currentConfig){
          if(!currentConfig){
            isInitOK=true;
            return;
          }
          if(currentConfig.sTdmId){
            self.initTdm(function(){
                self.initAegis(function(){
                  isInitOK=true;
                  isFunction(callback) && callback({
                    oAegis:aegisInstanse,
                    oTdm:window.TDM
                  });
                });
            });
          }else{
            self.initAegis(function(){
              isInitOK=true;
              isFunction(callback) && callback({
                oAegis:aegisInstanse
              });
            });
          }
      })
    },
    //初始化Aegis
    initAegis:function(callback){
      var self=this;
      if(!oCurrentConfig){
        callback(null);
        return;
      }
      if(aegisInstanse){
        isFunction(callback) && callback(aegisInstanse);
      }else{
        var uin=self.getUin();
        var id=oCurrentConfig.sAegisId;
        this.loadAegis(function(Aegis){
          var oInitAegisParams={
            id:id
          };
          //自定义参数：
          var oExtra=(isObject(oExtraParams.aegis)?oExtraParams.aegis:{});
          //如果有uin
          if(uin){
            oInitAegisParams.uin=uin;
          }
          //静态资源测速
          if(1 == oCurrentConfig.iReportAssetsSpeed){
            oInitAegisParams.reportAssetSpeed=true;
          }
          //cgi测速
          if(1 == oCurrentConfig.iReportCgiSpeed){
            oInitAegisParams.reportApiSpeed=true;
          }
          //http/https过滤
          if('all' != oCurrentConfig.sProtocolFilter){
            if(location.protocol.substr(0,location.protocol.length-1) != oCurrentConfig.sProtocolFilter){
              callback();
              return;
            }
          }
          //平台过滤
          if('pc' == oCurrentConfig.sPcMobileFilter){
            callback();
            return;
          }
          /*
            自定义额外参数相关:
          */
          //如果有onReport
          if(isFunction(oExtra.onReport)){
            oInitAegisParams.onReport=function(){
                //一系列初始化动作
                return oExtra.onReport.call(null,arguments);
            }
          }
          //如果有beforeReport
          if(isFunction(oExtra.beforeReport)){
            oInitAegisParams.beforeReport=function(log){
                //只上报milojs无关的报错
                if(isLogAboutMilo(log)){
                  return false;
                }
                fBeforeAegisReport(log,false);
                //一系列初始化动作
                return oExtra.beforeReport.call(null,arguments);
            }
          }else{
            oInitAegisParams.beforeReport=function(log){
                //只上报milojs无关的报错
                if(isLogAboutMilo(log)){
                  return false;
                }
                fBeforeAegisReport(log,false);
            }
          }
          aegisInstanse = new Aegis(oInitAegisParams);
          isFunction(callback) && callback(aegisInstanse);
        })
      }
    },
    //初始化Tdm
    initTdm:function(callback){
      var self=this;
      if(!oCurrentConfig){
        callback(null);
        return;
      }
      if(isTdmLoad){
        isFunction(callback) && callback(window.TDM)
      }else{
        var uin=self.getUin();
        var sTdmId=oCurrentConfig.sTdmId;
        this.loadTdm(function(Tdm){
          Tdm.init({
            env:"cn",
            appId: Number(sTdmId),
            appVer: ''+milo.config.version,
            userId: uin,
            channel: "milo"
          }).then(function(){
             isInitTdm=true;
             isFunction(callback) && callback();
          }).catch(function(errMessage){
              console.error(errMessage);
          });
        })
      }
    },
    //获取Aegis引用
    loadAegis:function(callback){
      if(window.Aegis){
          isFunction(callback) && callback(window.Aegis);
      }else{
          loadAegisCb.push(callback);
          if(isLoadingAegis){
            return;
          }
          isLoadingAegis=true;
          // if(isFunction(window.define)){
          //   need('https://cdn-go.cn/aegis/aegis-sdk/latest/aegis.min.js?bid=3977',function(Aegis){
          //     while(loadAegisCb.length){
          //       var cb=loadAegisCb.shift();
          //       isFunction(cb) && cb(Aegis);
          //     }
          //   })
          // }else{
          milo.loadScript('https://cdn-go.cn/aegis/aegis-sdk/latest/aegis.global.min.js',function(isLoad){
            if(!isLoad){
              return;
            }
            while(loadAegisCb.length){
              var cb=loadAegisCb.shift();
              isFunction(cb) && cb(window.Aegis);
            }
          })
          //}

      }
    },
    //获取tdm引用
    loadTdm:function(callback){
      if(window.TDM){
          isFunction(callback) && callback(window.TDM);
      }else{
          loadTdmCb.push(callback);
          if(isLoadingTdm){
            return;
          }
          isLoadingTdm=true;
          if(typeof window['define'] === 'function' && window['define'].amd){
          need('https://game.gtimg.cn/images/js/tdm/tdm.js',function(Tdm){
            if(!Tdm){
              return;
            }
              isTdmLoad=true;
              window.TDM=Tdm;
              callback(Tdm)
          })
        }else{
          milo.loadScript('https://game.gtimg.cn/images/js/tdm/tdm.js',function(isLoad){
            if(!isLoad){
              return;
            }
              isTdmLoad=true;
              while(loadTdmCb.length){
                var cb=loadTdmCb.shift();
                isFunction(cb) && cb(window.TDM);
              }
          })
        }
      }
    },
    getUin:function(){
      var acctype=milo.cookie.get('acctype'),uin='',appid=milo.cookie.get('appid');
      if(acctype){
        uin=milo.cookie.get('openid');
      }else{
        acctype='pt';
        uin=milo.cookie.get('uin');
      }
      if('pt' == acctype){
        if(uin){
          return acctype+'-'+uin;
        }
      }else if(/^(wx|qc|wg)$/.test(acctype)){
        if(uin && appid){
          return acctype+'-'+appid+'-'+uin;
        }else if(uin){
          return acctype+'-unknown-'+uin;
        }
      }
      return '';
    },
    //只监控milo相关的数据
    initForMilo:function(callback){
      var self=this;
      //loadStatus=1 pending
      if(1 == loadMiloStatus && isFunction(callback)){
          arrInitMiloCb.push(callback);
          return;
      }

      //loadStatus=2 loadOK
      if(2 == loadMiloStatus){
        isFunction(callback) && callback({
          oAegis:aegisInstanseForMilo
        });
        return;
      }

      //loadStatus=0
      loadMiloStatus=1;//pending
      arrInitMiloCb.push(callback);
      getDomainListConfig(function(oDomainConfig){
          if(!oDomainConfig || !oDomainConfig.config || !oDomainConfig.config.sAegisId){
              return;
          }
          var sAegisId=oDomainConfig.config.sAegisId;
          self.loadAegis(function(Aegis){
          var uin=self.getUin();
          var oInitParams={
            id:sAegisId,
            reportApiSpeed:true,
            reportAssetSpeed:true,
            beforeReport:function(log){
              //只上报milojs自身相关的报错
              if(!isLogAboutMilo(log)){
                return false;
              }
            }
          };
          if(uin){
            oInitParams.uin=uin;
          }
          aegisInstanseForMilo=new Aegis(oInitParams);
          loadMiloStatus=2;//loadOK
          isInitMiloOK=true;
          while(arrInitMiloCb.length){
            var tmpCb=arrInitMiloCb.shift();
            isFunction(tmpCb) && tmpCb({
              oAegis:aegisInstanseForMilo
            });
          }
        })
      });
    }
  }
  milo.loader.loadByTag([
    {
      name:'biz.frontmonitor',
      value:frontmonitor
    }
  ]);
})();

/*
@module  ATM
