    //**如callback不是function或不存在则不进行回调
    //**modules只作数组判断。
    if (!isArray(modules)) {
      modules = new Array(modules);
    }

    var mc = moduleContainer("", modules, callback);
    start(mc);
    //**考虑是否增咖中间过渡层，以增加通用性及可移值性
    //**下一期考虑扩展，允许本方法return得到一个对象，以直接使用对象的方法（talk）
    //**确实，需要如var myobj = need("....");这样的形式
    return undefined;
  };

