  function hitGrey(ruleArr, sUinWhiteList) {
    var isHit = false;
    if (!ruleArr || !ruleArr.length) {
      isHit = false;
      return isHit;
    }
    // 检查规则是否匹配
    for (var i = 0; i < ruleArr.length; i++) {
