(function () {
  var date = milo.date;
  var _d = new Date();
  extend(date, {
    /**
     * 获取日期
     * @param {string} sep 分隔符 默认为-
     * @return {string} yyyy-mm-dd
     */
    toDateString: function (nd) {
      var a = [],
        dt = isDate(nd) ? nd : _d;
      (m = dt.getMonth() + 1),
        (d = dt.getDate()),
        (sep = arguments[1]
          ? arguments[1]
          : isString(arguments[0])
          ? arguments[0]
          : "-");
      a.push(dt.getFullYear());
      a.push(m.toString().length < 2 ? "0" + m : m);
      a.push(d.toString().length < 2 ? "0" + d : d);
