//开启专属大区后过滤函数

function filterArea(areaId) {
    var arr_areaId = new Array();
    var jareaId = new Array();
    var area_server = new Array();
    var oAServer = new Object();
    var jServer = new Array();
    var recommend = new Array();
    var newj = new Array();
    var colSer = new Array();
    var cIndex = 0;

    arr_areaId = areaId.split("|");
    var arr_index = 0;
    for (var i = 0; i < arrAreaShowList.length; i++) {
        var jaId = arrAreaShowList[i]['sAreaID'];
        var bo = in_array(jaId, arr_areaId);
        if (bo) {
            jareaId[arr_index] = new Array();
            jareaId[arr_index]['sAreaID'] = arrAreaShowList[i]['sAreaID'];
            jareaId[arr_index]['sAreaName'] = arrAreaShowList[i]['sAreaName'];
            jareaId[arr_index]['sNetFlag'] = arrAreaShowList[i]['sNetFlag'];
            arr_index++;
        }
    }
    arrAreaShowList = jareaId; //重写大区数组
    
    console.log("arrAreaShowList.length:"+arrAreaShowList.length);
    //document.write(JSON_area[0]['sAreaID']+"<br/>");
    
    var str = '';
    for (var j = 0; j < arrAreaShowList.length; j++) {
        var sId = arrAreaShowList[j]['sAreaID'];
        //ADD BY RECAHRDYANG
        arrServerList = JSON_area_server[sId];
        
        if(parseInt(sId)==5095140)
        {
            arrTemp1 = new Array();
            arrTemp2 = new Array();
            arrTemp3 = new Array();
            
            arrTemp1 = arrServerList.reverse();
            
            arrTemp2 = JSON_area_server[6740044];
            
            arrTemp3 = JSON_area_server[7470368];
            
            if(arrTemp3)
            {
                arrTemp3 = arrTemp3.reverse();
                arrTemp2 = arrTemp2.reverse();
                    
                arrServerList = arrTemp3.concat(arrTemp2,arrTemp1);
            }
        }
        if(parseInt(sId)==7609651)
        {
            arrTemp4 = new Array();
            arrTemp5 = new Array();
            arrTemp4 = arrServerList.reverse();
            arrTemp5 = JSON_area_server[7609753];
            
            if(arrTemp5)
            {
                arrTemp5 = arrTemp5.reverse();
                
                arrServerList = arrTemp5.concat(arrTemp4);
            }
        }
        // if (parseInt(sId)==7609527){//公测
        //     console.log('公测');
        //     console.log(JSON_area_server[7609527]);
        //     arrTemp6 = new Array();
        //     arrTemp6 = JSON_area_server[7609527];
        //     arrTemp6 = arrTemp6.splice(1000);
        //     arrServerList = arrTemp6.reverse();
        //     console.log(arrServerList);
        //
        // }
        // if (parseInt(sId)==7609528){//公测1000+
        //     console.log('1000+')
        //     console.log(JSON_area_server[7609527]);
        //     arrTemp7 = new Array();
        //     arrTemp7 = JSON_area_server[7609527];
        //     arrTemp7 = arrTemp6.slice(999);
        //     arrServerList = arrTemp6.reverse();
        // }
        
        str += sId + ":[" + arrServerList + "],";
        if (typeof(arrServerList) != "undefined" && arrServerList.length != 0) {
            for (var s = 0; s < arrServerList.length; s++) {
                osId = arrServerList[s];
                oAServer[osId] = JSON_server[osId];
            }
        }
    }
    str = str.substring(0, str.length - 1);
    str = "{" + str + "}";
    str = eval('(' + str + ')');
    JSON_server = oAServer; //重写server数组
    JSON_area_server = str; //重写大区对应server数组
    for (var u = 0; u < arrAreaShowList.length; u++) {
        var sId = arrAreaShowList[u]['sAreaID'];
        //拼接所有专属大区服务器数组         
        for (var r = 0; r < JSON_area_server[sId].length; r++) {
            colSer[cIndex] = JSON_area_server[sId][r];
            cIndex++;
        }
    }
    var recommend_index = 0;
    for (var n = 0; n < JSON_recommend.length; n++) {
        var re = JSON_recommend[n];
        if (in_array(re, colSer)) {
            recommend[recommend_index] = re;
            recommend_index++;
        }
    }
    var new_index = 0;
    for (var m = 0; m < JSON_new.length; m++) {
        var ne = JSON_new[m];
        if (in_array(ne, colSer)) {
            newj[new_index] = ne;
            new_index++;
        }
    }
    JSON_recommend = recommend; //重写推荐server数组
    JSON_new = newj; //重写最新server数组

    //JSON_Telecom_iServerId,JSON_NetCom_iServerId,JSON_Crewel_iServerId首先判断是否存在，然后在重写
    if (typeof(JSON_Telecom_iServerId) != "undefined" && JSON_Telecom_iServerId != null) {
        var telBool = in_array(JSON_Telecom_iServerId, colSer);
        if (telBool == false) {
            JSON_Telecom_iServerId = null;
        }
    }
    if (typeof(JSON_NetCom_iServerId) != "undefined" && JSON_NetCom_iServerId != null) {
        var netBool = in_array(JSON_NetCom_iServerId, colSer);
        if (netBool == false) {
            JSON_NetCom_iServerId = null;
        }
    }
    if (typeof(JSON_Crewel_iServerId) != "undefined" && JSON_Crewel_iServerId != null) {
        var creBool = in_array(JSON_Crewel_iServerId, colSer);
        if (creBool == false) {
            JSON_Crewel_iServerId = null;
        }
    }

}

//判断一个元素是否在一个数组函数 added by yalizhao 

function in_array(str, arr_json) {
    for (var i = 0; i < arr_json.length; i++) {
        if (typeof(arr_json[i]) != "undefined" && arr_json[i] != null) {
            if (arr_json[i] == str) {
                return true;
            }
        }
    }
    return false;
}

