/**
 数组随机抽取方法
 */

function randArray(m, len) {
    m.sort(function() {
        return Math.random() - 0.5;
    });
    var re = m.slice(0, len);
    if (len > 1) {
        return re;
    } else {
        return re[0];
    }
}

