function selfSaveLoginServerId(ServerId) {
    TCSS('SaveServer', ServerId); //保存最近登录服务器点击流统计
    var Comm_result = {"status": -1, "message": "登录失败"};
    var save_url= qcConfigJs["selfLoginServerIdUrl"];
    if (save_url == "" || save_url == null) {
        console.log("error! no upload login serverID");
        return {"status": -1, "message": "登录连接错误"};
    } else {
        var sUrl = save_url + "?openid=" + milo.cookie.get("openid") + "&access_token=" + milo.cookie.get("access_token") + "&appid=" + milo.cookie.get("appid") + "&env=" + ServerId;
        $.ajax({
            url: sUrl,
            async: false,
            type: 'get',
            xhrFields: {
                withCredentials: true
            },
            success: function (data, status, xhr) {
                var csrf_token = xhr.getResponseHeader("X-Csrf-Token");
                console.log("csrf_token = ", csrf_token);
                // 获取csrf_token 后再次登录
                $.ajax({
                    url: sUrl,
                    async: false,
                    type: 'post',
                    data: {},
                    headers: {
                        "X-Csrf-Token": csrf_token,
                    },
                    xhrFields: {
                        withCredentials: true
                    },
                    success: function(result) {
                        var res = $.parseJSON(result);
                        if (typeof(res) != 'undefined' && res != null && res.status != 'undefined') {
                            Comm_result = res;
                            return res;
                        } else {
                            console.ERROR("get server_list error");
                            Comm_result = {"status": -1, "message": "登录失败"};
                        }
                    }
                })    
            }
        })
    }

    return Comm_result;
}

