function SetLastLoginServerByCookies(ServerId) {
    var openid = milo.cookie.get("openid");
    if (openid == null || openid == '') {
        return;
    }
    var server_data = {"playerlist": []};

    var lastLoginInfo = milo.cookie.get("tmpLastLoginInfo");
    if (lastLoginInfo != null && lastLoginInfo != '') {
        var login_json = JSON.parse(lastLoginInfo);
        var flag = false
        for (var idx = 0; idx < login_json.playerlist.length; idx++) {
            var env_info = login_json.playerlist[idx];
            if (env_info.openid == openid) {
                flag = true;
                // 如果id已有，就删除
                for (var jj=0; jj<env_info.zonelist.length; jj++){
                    if (env_info.zonelist[jj] == ServerId) {
                        login_json.playerlist[idx].zonelist.splice(jj, 1);
                        break;
                    }
                }

                // 先添加元素
                login_json.playerlist[idx].zonelist.push(ServerId);
                // 再判断是否删除
                if (login_json.playerlist[idx].zonelist.length > 3) {
                    login_json.playerlist[idx].zonelist.shift();
                }
                break;
            }
        }

        if (!flag) {
            var tmp_player = {
                "openid": openid,
                "zonelist": [ServerId]
            }
            login_json.playerlist.push(tmp_player);
        }

        server_data = login_json;
    } else {
        var tmp_player = {
            "openid": openid,
            "zonelist": [ServerId]
        }
        server_data.playerlist.push(tmp_player);
    }

    // 写回cookie
    var env_list_info = JSON.stringify(server_data);
    milo.cookie.set("tmpLastLoginInfo", env_list_info, 3600*24*30, qcConfigJs["setCookieUrl"], "/");
}

function GetLastLoginServerByCookies() {
    var qc_server_list = new Array();

    var openid = milo.cookie.get("openid");
    if (openid == null || openid == '') {
        return qc_server_list;
    }

    var lastLoginInfo = milo.cookie.get("tmpLastLoginInfo");
    if (lastLoginInfo == null || lastLoginInfo == '') {
        return qc_server_list;
    }

    var login_json = JSON.parse(lastLoginInfo);
    for (var idx=0; idx < login_json.playerlist.length; idx++) {
        env_info = login_json.playerlist[idx];
        if (env_info.openid == openid) {
            for (var yy=0; yy < env_info.zonelist.length; yy++) {
                qc_server_list.push(env_info.zonelist[yy]);
            }
        }
    }

    return qc_server_list;
}

