/**
 * 取得用户QQ号码
 * @return {number} uin,不存在则返回空
 */
LoginManager.getUserUin = function(){
	var uin = comm.getUserUin();
	if(!uin){
		return '';
	}

	var _realStr = milo.cookie.get("show_id");
	if(!_realStr){
		return uin;
	}

	//检查是否是电信号码，否则直接上传电信号
	var _getQQStr = function(realStr){
		var len = realStr.length;
		if(len % 2 != 0){
			return '';
		}
		var _qq = '';
		for(var i = 0; i < len; i+=2){
			_qq += String.fromCharCode(parseInt(realStr.substr(i, 2), 16));
		}
		return _qq;
	};
	var __uin = _getQQStr(_realStr);
	if(!isNaN(__uin)){
		return __uin;
	}

	return uin;
};
/**
