                d = comm.getAppId(d),
                c = comm.getUserUin();
            window.pt = {};
            pt.setHeader = function(avatarInfo) {
            	if(isObject(avatarInfo) && avatarInfo[c]){
            		a.userFace=avatarInfo[c];
            	}
            	isFunction(b) && b(a);
            };
			      var getUrl = "https://ssl.ptlogin2.qq.com/getface?appid=" + d + "&imgtype=3&encrytype=0&devtype=0&keytpye=0&uin=" + c;
            loadScriptLogin(getUrl,function(){
            	//b(a);
            });
        }, function() {
            b(a)
        })
    }
};
/*QQ互联登录*/
/*
	@param callback  登录回调
	@opt 传入的参数
	@isQcWx 标识是否是QcWx联合登录，如果是，则函数返回iframe的url
*/
LoginManager.qcLogin=function(callback,opt,isQcWx){
	var self=this;
	// qcLogin report
	ATM.reportATM({
		toappid: 38,
		tomoduletype: 21,
		tointer: 2,
		toreturncode: 0,
		businesstype: comm.getGameId(),
		result: 0,
		cgi: location.href,
		errormsg: 'qc pc login'
	});
	var logOption = {
		'gameId' : '',
		'appId' : '',
		'needMaskDiv':true,  //need edit
		'needReloadPage':true, //登录成功以后刷新页面
        'loginDivOffset':{left:0.5,top:0.5},
		'msg' : '正在获取登录信息，请稍候...',
        'loginedCallback':null,
		'type' : 'float',
		'loginFrame' : 'loginHTMLFrame',
		'css' : '',
		's_url' : ''
	};

	if(typeof(callback) != 'function' && typeof(callback) == 'object'){
		opt = callback;
		callback = null;
	}

	extendLess(logOption, option);
	//extendLess(logOption, opt);
	extend(logOption, opt);
	var qcOption=option.oQQConnectParams || {
		appId:"101491592",
		scope:"get_user_info",
		redirect_uri:"https://milo.qq.com/comm-htdocs/login/qc_redirect.html",
		state:"STATE"
	};
	if(logOption.oQQConnectParams){
		extend(qcOption,logOption.oQQConnectParams);
	}
	if(opt && opt.needReloadPage){
		logOption.needReloadPage=opt.needReloadPage;
	}else{
		logOption.needReloadPage = (isFunction(callback)) ? false : logOption.needReloadPage;
	}

	window.qqConnectCallback=function(codeOption){
		if(!codeOption || !codeOption.code){
			alert("抱歉，参数错误，请重新登录");
			if(isQcWx){
				qcWxFrame.close();
			}else{
				qqConnectFrame.close();
			}
			return;
		}
		if(codeOption.state != qcOption.state){
			alert("抱歉，来源校验错误，请重新登录");
			if(isQcWx){
				qcWxFrame.close();
			}else{
				qqConnectFrame.close();
			}
			return;
		}
		var doCallbackName="doCallback_"+Math.ceil(10000*Math.random());
		window[doCallbackName]=function(userInfo){
			if(0!=userInfo.errorCode){//出错了
				alert("抱歉，请重新登录");
				if(isQcWx){
					qcWxFrame.close();
				}else{
					qqConnectFrame.close();
				}
				return;
			}
			var logInfo={
				openid:milo.cookie.get("openid"),
				userUin:'',
				uin: '',
				nickName:userInfo.nickName,
				nickname:userInfo.nickName ? decodeURIComponent(userInfo.nickName): '',
				userLoginTime:parseInt(new Date().getTime()/1000),
				loginType:'qc',
				logtype: 'qc',
				expires:86400
			}
			var value = milo.serialize(logInfo);
			milo.cookie.set("IED_LOG_INFO2_QC",value,600,location.host,"/");
			//头像
			if(userInfo.face){
				comm.storeUserFace(logInfo.openid,userInfo.face);
			}
			//回调，不刷新页面
			if (!logOption.needReloadPage) {
				//先关闭弹框
				if(isQcWx){
					qcWxFrame.close();
				}else{
					qqConnectFrame.close();
				}
				//执行回调
				var isLogin = comm.checkUserLogined();
				if(isLogin){
					cb.loginedCallback();
					if (isFunction(callback))  callback();
				}else{
					cb.unloginCallback();
				}
			}else{
				//刷新页面
				window.location.reload();
			}
		}

		//请求codeToOpenid 拿openid和access_token
		//......
		need('util.jquery',function($){
			var params={
				a:'qcCodeToOpenId',
				qc_code:codeOption.code,
				appid:qcOption.appId,
				redirect_uri:qcOption.redirect_uri
			}
			$.ajax({
				url:'https://ams.game.qq.com/ams/userLoginSvr?'+milo.serialize(params),
				type:"GET",
				dataType:'jsonp',
				success:function(retObj){
					if(0==retObj.iRet){
						var data=retObj;
						var expires_in=data.expires_in || 86400;
						milo.cookie.set("openid",data.openid,expires_in,location.host,"/");
						milo.cookie.set("access_token",data.access_token,expires_in,location.host,"/");
						milo.cookie.set("appid",qcOption.appId,expires_in,location.host,"/");
						milo.cookie.set("acctype","qc",expires_in,location.host,"/");
						//milo.cookie.set("refresh_token",data.refresh_token,86400,"qq.com","/");
						/*var acctype = 'qq';
						var appid = qcOption.appId;
						var openid = data.openid;
						var access_token = data.access_token;*/
						loadScriptLogin(comm.getCheckLoginUrl(option.gameId) + '?callback=' + doCallbackName + '&acctype=' + 'qc' + '&appid=' + qcOption.appId + '&openid=' + data.openid + '&access_token=' + data.access_token+"&game="+comm.getGameId(), function(loaded){
						});

					}else{
						self.logout(function(){
							alert(retObj.sMsg);
							if(isQcWx){
								qcWxFrame.close();
							}else{
								qqConnectFrame.close();
							}
						});

					}
				},
				error:function(){

				}
			})
		})
	}
	var loginUrl='https://graph.qq.com/oauth2.0/authorize?response_type=code';
	var loginOpt={
		state:qcOption.state,
		client_id:qcOption.appId,
		redirect_uri:qcOption.redirect_uri || "https://milo.qq.com/comm-htdocs/login/qc_redirect.html?parent_domain="+encodeURIComponent(location.protocol+"//"+location.host)
	}
	if(-1 == loginOpt.redirect_uri.indexOf('parent_domain=')){
		loginOpt.redirect_uri+=(loginOpt.redirect_uri.indexOf('?')>-1?'&':'?')+'parent_domain='+encodeURIComponent(location.protocol+"//"+location.host);
	}
	//loginOpt.redirect_uri=encodeURIComponent(loginOpt.redirect_uri);
	loginUrl+="&"+milo.serialize(loginOpt);
	//如果是QcWx联合登录，则返回loginUrl
	if(isQcWx){
		return loginUrl;
	}else{
		qqConnectFrame.show(loginUrl);
	}
}
