	milo.cookie.clear('wxcode', location.host, '/');

	milo.cookie.clear("login_origin", location.host, "/");


	//保证注销回调只执行一次
	var logoutCallbackLock=2;

	window["logoutWxCallback"] = window["logoutCallback"] = function(){
		logoutCallbackLock--;//减少一次，说明有一个域名下已经注销
		cb.unloginCallback();
