	var oWxIFrame = document.createElement("iframe");
	oWxIFrame.id = "loginWxIframe";
	oWxIFrame.name = "loginWxIframe";
	oWxIFrame.scrolling="no";
	oWxIFrame.frameBorder ="0";
	oWxIFrame.style.display ="none";
	document.body.appendChild(oWxIFrame);
    oWxIFrame.src=location.protocol+"//apps.game.qq.com/ams/logout_wx.html";
	//清除game.qq.com下的cookie
	var sLogoutGameUrl = location.protocol+"//game.qq.com/act/logout.html";
	if(logOption.isNotForceClearPt){
		sLogoutGameUrl = sLogoutGameUrl + '?isNotForceClearPt=1';
	} 
	logWin.openLoginDiv({
		src :sLogoutGameUrl
	});

	if (!pageSupportDomain) {
		postMessageProxy.addEventListener("loginManager_logout_WX", "logoutWxCallback");
		postMessageProxy.addEventListener("loginManager_logout_QQ", "logoutCallback");
	}
};

/**
 * 检查是否登陆，并执行对应回调
 * @param {function} logincallback 已登陆的回调
 * @param {function} unlogincallback 未登陆的回调
 * @param {object} opt 登陆配置项
 * @return {undefined}
 */
LoginManager.checkLogin = function(logincallback, unlogincallback, opt){
	// check reallogin report
	ATM.reportATM({
		toappid: 38,
		tomoduletype: 21,
		tointer: 11,
		toreturncode: 0,
		businesstype: comm.getGameId(),
		result: 0,
		cgi: location.href,
		errormsg: 'check login'
	});
	option = extend(option, opt);

	if (comm.isDouYuLoginStatus()) {
		cb.loginedCallback();
		if (isFunction(logincallback)) logincallback()
		return;
	}
	if (window.iUseQQConnect === 1 && !milo.cookie.get('acctype')) {
		cb.unloginCallback();
		if (isFunction(unlogincallback)) unlogincallback();
		return;
	}

	if (comm.checkUserLogined()  ){
		cb.loginedCallback();

		if (isFunction(logincallback) ){
			if ( !milo.cookie.get("wxcode")){
					var user=milo.unSerialize(comm.getIED_LOG_INFO())
					/*
						QQ互联登录态改造期间，临时允许pt与qc共存，【PT下线后删除改逻辑】 -----Start-----
					*/
					if('qc' == user.logtype && 1 != option.iUseQQConnect){
						user.logtype='pt';
						user.loginType='pt'
						user.openid='';
					}

					/*
						QQ互联登录态改造期间，临时允许pt与qc共存，【PT下线后删除改逻辑】 -----End-----
					*/
					//互联，wegame登录带上face
					if(/^(qc|wg|ks)$/.test(user.logtype) && comm.getUserFaceData(user.openid)){
						user.face=comm.getUserFaceData(user.openid);
					}
					logincallback(user);
			}else{

				LoginManager.wxRenderWhenLogined(logincallback);
			}
		}

	}else{

		var callbackName = 'jsonp' + milo.randomInt(100);
		comm.callbackLoginInfo(callbackName, function(IED_LOG_INFO2){
			var isLogin = comm.checkUserLogined();
			//_______isRunFirstMilo 代表是否正在请求登录cgi校验登录态，如果是，则将回调先缓存，如果不是，则请求远程cgi，并置为1
			//LoginManager._______isRunFirstMilo = 2;
			LoginManager._______isRunFirstMilo = 0;
			if(isLogin){
				cb.loginedCallback();
				if (isFunction(logincallback) ){
					if ( !milo.cookie.get("wxcode")){
							var user={
								"uin":comm.getUserUin(),
								"userUin":IED_LOG_INFO2.userUin,
								"nickname":comm.getNickName(),
								"nickName":IED_LOG_INFO2.nickName,
								"logtype":IED_LOG_INFO2.loginType || milo.cookie.get('acctype') || "qq",
								"loginType":IED_LOG_INFO2.loginType || milo.cookie.get('acctype') || "qq",
								'face':IED_LOG_INFO2.face || ''
							}
							if(/^(qc|wg|ks)$/.test(user.logtype)){
								user.openid=milo.cookie.get('openid') || '';
							}

							//头像缓存
							if(user.face && /^(qc|wg|ks)$/.test(user.logtype)){
								comm.storeUserFace(user.openid,user.face);
							}
							logincallback(user);
					}else{

						//LoginManager.wxRenderWhenLogined(logincallback,callbackName);
					}
				}

			}else{

				cb.unloginCallback();
				if (isFunction(unlogincallback)) unlogincallback();
			}

			while(true){
				if(LoginManager.logincallbackArray.length <= 0){
					break;
				}
				var temp = LoginManager.logincallbackArray.shift();
				temp(IED_LOG_INFO2);
			}
			LoginManager._______isRunFirstMilo = 0;
		});


		if(!LoginManager.logincallbackArray){
			LoginManager.logincallbackArray = [];
		}

		if(typeof(LoginManager._______isRunFirstMilo) == 'undefined'){
			LoginManager._______isRunFirstMilo = 0;
		}

		// _______isRunFirstMilo checklogin执行的状态表示，如果是0那么是第一次执行，如果不是0状态为正在执行

		if (LoginManager._______isRunFirstMilo != 0){
			LoginManager.logincallbackArray.push(window[callbackName]);
			return;
		}

		LoginManager._______isRunFirstMilo = 1;

		var acctype = requestLoginParam('acctype');
		//qc
		if(!acctype && 'qc'==milo.cookie.get('acctype')){
			acctype='qc';
		}
		//wegame
		if(!acctype && 'wg'==milo.cookie.get('acctype')){
			acctype='wg';
		}
		//ks
		if(!acctype && 'ks'==milo.cookie.get('acctype')){
			acctype='ks';
		}
		if(acctype == "weixin"){
			acctype = "wx";
		}
		var appid = requestLoginParam('appid');
		var openid = requestLoginParam('openid');

		var access_token = acctype=="wx"?requestLoginParam('access_token'):requestLoginParam('openkey');

		//add susahuang 支持页游openid、accesstoken传参方式
		if(location.host == "cfw.qq.com"){
			access_token = requestLoginParam('access_token');
		}
		//判断登录方式，如果是qc，则从cookie中取相关cookie
		if("qc" == acctype){
			appid=appid || milo.cookie.get('appid');
			openid=openid || milo.cookie.get('openid');
			access_token=access_token || milo.cookie.get('access_token');
			/*
				QQ互联登录态改造期间，临时允许pt与qc共存，【PT下线后删除改逻辑】 -----Start-----
			*/
			//如果本页面不走qc则，继续走pt
			if(option.iUseQQConnect != 1){
				appid='';
				openid='';
				access_token='';
				acctype='';
			}
			/*
				QQ互联登录态改造期间，临时允许pt与qc共存，【PT下线后删除改逻辑】 -----Start-----
			*/
		}
		//判断登录方式，如果是ks，则从cookie中取相关cookie
		if ("ks" == acctype) {
			appid = milo.cookie.get('appid');
			openid = milo.cookie.get('openid');
			access_token = milo.cookie.get('access_token');
		}
		//wegame 登录态
		if('wg'==acctype){
			appid=milo.cookie.get('appid') || '';
			access_token=milo.cookie.get('access_token') || '';
			openid=milo.cookie.get('openid') || '';
			//续期专用
			refresh_token=milo.cookie.get('refresh_token') || '';
			loadScriptLogin(comm.getCheckLoginUrl(option.gameId) + '?callback=' + callbackName + '&acctype=' + acctype + '&appid=' + appid + '&openid=' + openid + '&access_token=' + access_token+"&refresh_token="+refresh_token, function(loaded){
			});
		}else if(acctype){
			loadScriptLogin(comm.getCheckLoginUrl(option.gameId) + '?callback=' + callbackName + '&acctype=' + acctype + '&appid=' + appid + '&openid=' + openid + '&access_token=' + access_token+"&game="+comm.getGameId(), function(loaded){
			});
		}else{
			//如果是微信扫码登陆，则先进行codeToOpenId动作
			var wxcode = requestLoginParam('code');
			if (wxcode && !milo.cookie.get("openid") ){

				//执行微信的code转openID
				LoginManager.doWxCodeToOpenId(wxcode,function(openidInfo){
					var originalUrl= decodeURIComponent(requestLoginParam('originalUrl'));
					//openid拿到后，先做一次跳转，去掉URL上的code，appid等传值
					/*if(location.protocol == "https:"){
						window.top.location.href=originalUrl;
					}else{
						document.location.href=originalUrl;
					}*/
					//新的回调方式
					if(isFunction(parent.milo_WxLoginCallback)){
						parent.milo_WxLoginCallback();
					}else{
						//老的方式，跳转
						if(milo.xss.isSafeUrl(originalUrl)){
							document.location.href=originalUrl;
						}
					}
				});


			}else if (milo.cookie.get("wxcode")){
				//有微信code，说明已经微信登录了，直接走wxRenderWhenLogined,_______isRunFirstMilo置为0，不走callback  缓存了。
				LoginManager._______isRunFirstMilo=0;
				LoginManager.wxRenderWhenLogined(logincallback);
			}else{
				//调用后端接口，通过和_______isRunFirstMilo结合，使用callback 缓存控制，使所有回调生效，同时避免多次调用后端接口
				loadScriptLogin(comm.getCheckLoginUrl(option.gameId) + '?callback=' + callbackName+"&game="+comm.getGameId(), function(loaded){});
			}
		}
	}
};

/**
 * 发请求强校验否登陆，并执行对应回调
 * @param {function} logincallback 已登陆的回调
 * @param {function} unlogincallback 未登陆的回调
 * @param {object} opt 登陆配置项
 * @return {undefined}
 */
LoginManager.checkRealLogin = function(logincallback, unlogincallback, opt){
	// check reallogin report
	ATM.reportATM({
		toappid: 38,
		tomoduletype: 21,
		tointer: 12,
		toreturncode: 0,
		businesstype: comm.getGameId(),
		result: 0,
		cgi: location.href,
		errormsg: 'checkReal login'
	});
	option = extend(option, opt);
	var callbackName = 'jsonp' + milo.randomInt(100);
	comm.callbackLoginInfo(callbackName, function(IED_LOG_INFO2){
		var isLogin = comm.checkUserLogined();
		//_______isRunFirstMilo 代表是否正在请求登录cgi校验登录态，如果是，则将回调先缓存，如果不是，则请求远程cgi，并置为1
		LoginManager._______isRunFirstMilo = 0;
		if(isLogin){
			cb.loginedCallback();
			if (isFunction(logincallback)){
				if (!milo.cookie.get("wxcode")) {
					var user = {
						uin: comm.getUserUin(),
						userUin: comm.getUserUin(),
						nickName: IED_LOG_INFO2.nickName,
						nickname: comm.getNickName(),
						logtype: IED_LOG_INFO2.loginType || milo.cookie.get('acctype') || "qq",
						loginType: IED_LOG_INFO2.loginType || milo.cookie.get('acctype') || "qq",
						face: IED_LOG_INFO2.face || ''
					}
					if(/^(qc|wg|ks)$/.test(user.logtype)){
						user.openid=milo.cookie.get('openid') || '';
						//头像缓存
						if(user.face){
							comm.storeUserFace(user.openid,user.face);
						}
					}
					logincallback(user);
				} else {
					LoginManager.wxRenderWhenLogined(logincallback,callbackName);
				}
			}

		}else{
			cb.unloginCallback();
			if (isFunction(unlogincallback)) {
				unlogincallback();
			}
		}

		while(LoginManager.logincallbackArray.length) {
			var loginCb = LoginManager.logincallbackArray.shift();
			loginCb(IED_LOG_INFO2);
		}

	});

	if(!LoginManager.logincallbackArray){
		LoginManager.logincallbackArray = [];
	}

	// _______isRunFirstMilo checklogin执行的状态表示，如果是0或undefined那么是第一次执行，如果是1状态为正在执行,则把回调函数入栈
	if (LoginManager._______isRunFirstMilo == 1){
		LoginManager.logincallbackArray.push(window[callbackName]);
		return;
	}

	LoginManager._______isRunFirstMilo = 1;

	var acctype = requestLoginParam('acctype') || milo.cookie.get('acctype');
	if(acctype == "weixin") {
		acctype = "wx";
	}
	var access_token = (acctype == "wx" || location.host == "cfw.qq.com") ? //支持页游openid、accesstoken传参方式
		requestLoginParam('access_token') : requestLoginParam('openkey');
	access_token = access_token || milo.cookie.get('access_token') || '';

	var urlParams = {
		callback: callbackName,
		acctype: acctype,
		appid: requestLoginParam('appid') || milo.cookie.get('appid') || '',
		openid: requestLoginParam('openid') || milo.cookie.get('openid') || '',
		access_token: access_token,
		game: comm.getGameId()
	}

	if (acctype) {
		if ('qc' == acctype) {
			/*
				QQ互联登录态改造期间，临时允许pt与qc共存，【PT下线后删除改逻辑】 -----Start-----
			*/
			//如果本页面不走qc则，继续走pt
			if(option.iUseQQConnect != 1){
				extend(urlParams, {
					appid: '',
					openid: '',
					access_token: '',
					acctype: ''
				})
			}
		}
		//wegame 登录态
		if('wg' == acctype || 'ks' == acctype) {
			params.appid = milo.cookie.get('appid') || '';
			params.openid = milo.cookie.get('openid') || '';
			params.access_token = milo.cookie.get('access_token') || '';
			//续期专用
			params.refresh_token=milo.cookie.get('refresh_token') || '';
		}
		loadScriptLogin(comm.getCheckLoginUrl(option.gameId) + comm.buildParams(urlParams), function(loaded){
		});
	} else {
		//如果是微信扫码登陆，则先进行codeToOpenId动作
		var wxcode = requestLoginParam('code');
		if (wxcode && !milo.cookie.get("openid") ){

			//执行微信的code转openID
			LoginManager.doWxCodeToOpenId(wxcode,function(openidInfo){
				var originalUrl= decodeURIComponent(requestLoginParam('originalUrl'));
				//新的回调方式
				if(isFunction(parent.milo_WxLoginCallback)){
					parent.milo_WxLoginCallback();
				}else{
					//老的方式，跳转
					if(milo.xss.isSafeUrl(originalUrl)){
						document.location.href=originalUrl;
					}
				}
			});
		} else {
			//调用后端接口，通过和_______isRunFirstMilo结合，使用callback 缓存控制，使所有回调生效，同时避免多次调用后端接口
			loadScriptLogin(comm.getCheckLoginUrl(option.gameId) + '?callback=' + callbackName+"&game="+comm.getGameId(), function(loaded){});
		}
	}
};

//如果微信登陆了，就执行微信的登陆成功获取用户信息的回调
LoginManager.wxRenderWhenLogined=function(logincallback){
	var openId=milo.cookie.get("openid");
	var access_token=milo.cookie.get("access_token");
	LoginManager.getUserInfoByWxOpenId({"openid":openId,
									"access_token":access_token},function(wxUserInfo){
										if (isFunction(logincallback) && wxUserInfo)	{
											wxUserInfo.logtype="wx";
											wxUserInfo.loginType="wx";
											LoginManager.wxUserInfo=wxUserInfo;

											if (isDom(g(option.loginedDiv))){
												g(option.loginedDiv).style.display = "block";
											}
											if (isDom(g(option.unloginDiv))){
												g(option.unloginDiv).style.display = "none";
											}
											if (isDom(g(option.userinfoSpan))){
												//兼容milo-min中没有xss对象的情况
												g(option.userinfoSpan).innerHTML =milo.xss.filterWxNickName(wxUserInfo.nickname);
											}

											logincallback(wxUserInfo);

										}
									});



	//定义后台登陆接口的回调
	var callbackName = 'jsonp' + milo.randomInt(100);
	window[callbackName] = function(IED_LOG_INFO2){
		if(IED_LOG_INFO2.isLogin){
			var loginInfo = milo.cookie.get('IED_LOG_INFO2');
			if(loginInfo){
				loginInfo = milo.unSerialize(loginInfo);
			}else{
				loginInfo = {};
			}
			if(IED_LOG_INFO2.loginType == "qq" || IED_LOG_INFO2.loginType == "wx"){
				loginInfo.userUin = IED_LOG_INFO2.openid;
				loginInfo.uin = IED_LOG_INFO2.openid;
			}else{
				loginInfo.userUin = IED_LOG_INFO2.userUin;
				loginInfo.uin = IED_LOG_INFO2.userUin;
			}
			loginInfo.loginType = 'wx';
			loginInfo.logtype = 'wx'
			loginInfo.nickName = IED_LOG_INFO2.nickName;
			loginInfo.nickname = IED_LOG_INFO2.nickName ? decodeURIComponent(IED_LOG_INFO2.nickName) : '';
			loginInfo.userLoginTime = IED_LOG_INFO2.userLoginTime;
			var value = milo.serialize(loginInfo);

			milo.cookie.set("IED_LOG_INFO2",value,null,"qq.com","/");

		}else{
			comm.clearLOG_INFO_2();
		}


		//add susahuang 2017/6/24 check login
		var __tointer = 1;
		if(comm.getCheckLoginUrl(comm.getGameId()).indexOf('//commwebgame.game.qq.com/comm-cgi-bin/login/LoginReturnInfo.cgi') > -1){
			__tointer = 2;
		}else if(comm.getCheckLoginUrl(comm.getGameId()).indexOf('//ams.game.qq.com/ams/userLoginSvr') > -1){
			__tointer = 3;
		}
		ATM.reportATM({
			toappid: 1,
			tomoduletype: 100,
			tointer: __tointer,
			toreturncode: IED_LOG_INFO2.errorCode == 0 ? 0 : 1,
			businesstype: comm.getGameId(),
			result: IED_LOG_INFO2.errorCode,
			cgi: location.href,
			errormsg: IED_LOG_INFO2.errorStr
		});
	}

	//执行后台登陆接口，获取IED_LOG_INFO2
	option.logtype=3;
	loadScriptLogin(comm.getCheckLoginUrl(option.gameId) + '?callback=' + callbackName, function(loaded){});


}





//执行微信的code转openID
LoginManager.doWxCodeToOpenId=function(wxcode,callback){


	var serviceType= requestLoginParam('sServiceType');
		var appid= requestLoginParam('appid');
		var wxcodeToOpenidUrl = 'https://apps.game.qq.com/ams/ame/codeToOpenId.php?appid='+ appid + '&wxcode='+ wxcode + '&sServiceType=' + serviceType + '&wxcodedomain=' + window.location.host + '&acctype=wx';

		var  doCodeToOpenID=function(){
			$.ajax(wxcodeToOpenidUrl,{
				"dataType":"jsonp",
				"success":function(objData){
					//console.log(objData);
					if (objData.iRet===0){
						var  openidInfo= $.parseJSON(objData.sMsg);
						var expires_in=openidInfo.expires_in || 7200;//默认为7200
						milo.cookie.set("wxcode",wxcode,expires_in,"qq.com","/");
						milo.cookie.set("openid",openidInfo.openid,expires_in,"qq.com","/");
						milo.cookie.set("access_token",openidInfo.access_token,expires_in,"qq.com","/");
            			//refresh_token
            			milo.cookie.set('iegams_refresh_token',openidInfo.refresh_token,expires_in,'qq.com','/');
						milo.cookie.set("acctype","wx",expires_in,"qq.com","/");
						//种appid
						milo.cookie.set("appid",appid,expires_in,"qq.com","/");

						milo.cookie.set("login_origin", "milo", expires_in, location.host, "/");

						if (isFunction(callback)){
							callback(openidInfo);
						}

						//add susahuang 2017/6/24 code to openid reportatm
						ATM.reportATM({
							toappid: 1,
							tomoduletype: 32,
							tointer: 2,
							toreturncode: 0,
							businesstype: comm.getGameId(),
							result: objData.iRet,
							serialnum: objData.sLogSerialNum,
							cgi: location.href,
							errormsg: objData.sMsg
						});

					}else{
						alert("获取登录态失败!");
						if (isFunction(callback)){
							callback(openidInfo);
						}
						//add susahuang 2017/6/24 code to openid reportatm
						ATM.reportATM({
							toappid: 1,
							tomoduletype: 32,
							tointer: 2,
							toreturncode: 1,
							businesstype: comm.getGameId(),
							result: objData.iRet,
							serialnum: objData.sLogSerialNum,
							cgi: location.href,
							errormsg: objData.sMsg
						});
						return;
					}
				},
				error:function(xhr,errInfo,errObj){
					if(xhr.status != 200){
						ATM.reportATM({
							toappid: 1,
							tomoduletype: 32,
							tointer: 1,
							toreturncode: 1,
							businesstype: comm.getGameId(),
							result: 0-xhr.status,
							serialnum: "",
							cgi: location.href,
							errormsg: xhr.statusText
						});
					}else{
						var errormsg="";
						if(errInfo){
							errormsg+=errInfo.toString();
						}
						if(errObj){
							errormsg+="("+errObj.message+")";
						}
						//一般为返回内容错误，解析错误等
						ATM.reportATM({
							toappid: 1,
							tomoduletype: 32,
							tointer: 1,
							toreturncode: 1,
							businesstype: comm.getGameId(),
							result: 0-xhr.status,
							serialnum: "",
							cgi: location.href,
							errormsg: errormsg
						});
					}
				}

			});

		}

		//根据页面上是否已经加载了jquery ，觉得自己是否要加载jquery
		if (typeof(jQuery)!='undefined'){
			doCodeToOpenID();
		}else{
			need(["util.jquery"],function($){
				doCodeToOpenID();
			});
		}




}

//getUserInfo请求队列机制
/*
	当同一时段内有多个请求同时发出时，则缓存除第一个请求之外的其它请求，
	等第一个请求有响应的时候再遍历其它请求的回调函数直接执行

*/
LoginManager.wxUserInfoRequestQueue={
	//队列数据
	//格式：
	/*
		{
			"openid1_token1":[cb1,cb2,cb3],
			"openid2_token2":[cb1,cb2,cb3],
		}
	*/
	queueList:{

	},
	//指定请求是否有在等待
	isWaiting:function(openid,access_token,lang){
		var k=openid+'_'+access_token+'_'+lang;
		return (this.queueList[k] && this.queueList[k].length);
	},
	//添加请求到队列
	add:function(openid,access_token,lang,callback,errCallback){
		var k=openid+'_'+access_token+'_'+lang;
		if(!this.queueList[k]){
			this.queueList[k]=[{
				success:callback,
				fail:errCallback
			}];
		}else{
			this.queueList[k].push({
				success:callback,
				fail:errCallback
			});
		}
	},
	//执行队列
	run:function(openid,access_token,lang,wxUserData){
		var cbArr=this.queueList[openid+'_'+access_token+'_'+lang];
		while(cbArr && cbArr.length){
			var cbObj=cbArr.shift();
			//成功回调
			if(0 == wxUserData.iRet && isFunction(cbObj.success)){
				cbObj.success(wxUserData.data);
			}else if(0 !== wxUserData.iRet && isFunction(cbObj.fail)){//失败回调
				cbObj.fail(wxUserData);
			}
		}
	}
};
//根据微信的OpenId获取用户信息，昵称，头像等
LoginManager.getUserInfoByWxOpenId=function(opt,callback,errCallback){
	var self=this;
	var lang=opt.lang || option.wxLang;//返回的用户信息语言
	//apps的微信代理接口
	var wxuserapi_url="https://apps.game.qq.com/ams/ame/getWXUser.php?access_token="+opt.access_token+"&openid="+opt.openid+'&lang='+lang;
	var emojicss="https://ossweb-img.qq.com/images/js/milo/biz/widget/emoji/emoji.css";
	var doGetUserInfo=function(){
		if(self.wxUserInfoRequestQueue.isWaiting(opt.openid,opt.access_token,lang)){
			self.wxUserInfoRequestQueue.add(opt.openid,opt.access_token,lang,callback,errCallback);
			return;
		}
		self.wxUserInfoRequestQueue.add(opt.openid,opt.access_token,lang,callback,errCallback);
		$.ajax(wxuserapi_url,{
			"dataType":"jsonp",
			//"jsonpCallback":"callback",
			"success":function(wxUserData){
				//console.log(wxUserData);
				//请求数据添加到缓存
				comm.storeWxUserInfo(opt.openid,opt.access_token,lang,wxUserData);
				if (wxUserData.iRet===0){
					var  userinfo= wxUserData.data;
					if ($("head").find("link[href='"+emojicss+"']").length==0){
						loadCSS(emojicss,function(){
							//if (callback){
								self.wxUserInfoRequestQueue.run(opt.openid,opt.access_token,lang,wxUserData);
							//}
						});
					}else{
						//if (callback){
								self.wxUserInfoRequestQueue.run(opt.openid,opt.access_token,lang,wxUserData);
						//}
					}

					//add susahuang 2017/6/24 获取微信用户基本信息 reportatm
					ATM.reportATM({
						toappid: 1,
						tomoduletype: 32,
						tointer: 3,
						toreturncode: 0,
						businesstype: comm.getGameId(),
						result: wxUserData.iRet,
						serialnum: wxUserData.sLogSerialNum || "",
						cgi: location.href,
						errormsg: wxUserData.sMsg
					});
				}else{
					//add susahuang 2017/6/24 获取微信用户基本信息 reportatm
					ATM.reportATM({
						toappid: 1,
						tomoduletype: 32,
						tointer: 3,
						toreturncode: 1,
						businesstype: comm.getGameId(),
						result: wxUserData.iRet,
						serialnum: wxUserData.sLogSerialNum || "",
						cgi: location.href,
						errormsg: wxUserData.sMsg
					});
					//失败回调
					self.wxUserInfoRequestQueue.run(opt.openid,opt.access_token,lang,wxUserData);
					//LoginManager.logout();
				}


			},
			//上报非200的情况
			error:function(xhr,errInfo,errObj){
				if(xhr.status != 200){
					ATM.reportATM({
						toappid: 1,
						tomoduletype: 32,
						tointer: 3,
						toreturncode: 1,
						businesstype: comm.getGameId(),
						result: 0-xhr.status,
						serialnum: "",
						cgi: location.href,
						errormsg: xhr.statusText
					});
				}else{
					var errormsg="";
					if(errInfo){
						errormsg+=errInfo.toString();
					}
					if(errObj){
						errormsg+="("+errObj.message+")";
					}
					//一般为返回内容错误，解析错误等
					ATM.reportATM({
						toappid: 1,
						tomoduletype: 32,
						tointer: 3,
						toreturncode: 1,
						businesstype: comm.getGameId(),
						result: 0-xhr.status,
						serialnum: "",
						cgi: location.href,
						errormsg: errormsg
					});
				}
			}

		});

	}
	//如果有缓存内容，则取缓存内容
	if(opt.openid && opt.access_token && comm.getWxUserInfo(opt.openid,opt.access_token,lang)){
		var wxUserData=comm.getWxUserInfo(opt.openid,opt.access_token,lang);
		//成功回调
		if(0 == wxUserData.iRet && isFunction(callback)){
			callback(wxUserData.data);
		}else if(0 !== wxUserData.iRet && isFunction(errCallback)){//失败回调
			errCallback(wxUserData);
		}
		return;
	}
	//没有缓存的情况下
	//根据页面上是否已经加载了jquery ，觉得自己是否要加载jquery
	if (typeof(jQuery)!='undefined'){
		doGetUserInfo();
	}else{
		need(["util.jquery"],function($){
			doGetUserInfo();
		});
	}


}


