}

.ost-rank .rank-img {
  position: absolute;
  width: 200px;
  height: 90px;
  top: 0;
  left: 0;
  opacity: 0;
  display: none;
}

.ost-rank .rank-btn-bar {
  position: absolute;
  width: 100%;
  height: 28px;
  text-align: center;
  background: rgba(0, 0, 0, 0.7);
  bottom: 0;
  left: 0;
  display: none;
}

.ost-rank .rank-btn {
  float: left;
  width: 50%;
  font-size: 14px;
  line-height: 28px;
  color: #fff;
}

.ost-rank .rank-btn:hover .download-text {
  display: none;
}

.ost-rank .rank-btn:hover .download-btn {
  display: block;
}

.ost-rank .rank-order {
  position: absolute;
  top: 0;
  left: 0;
  font-size: 12px;
  width: 16px;
  height: 16px;
  text-align: center;
  line-height: 16px;
  color: #fff;
  background-color: #ccc;
  display: none;
}

.ost-rank .download-btn {
  width: 50%;
  height: 30px;
  float: left;
}

.ost-rank .download-btn:after {
  content: "";
  width: 30px;
  height: 30px;
  display: inline-block;
  margin-top: -1px;
  background: url(./title_sprite.png);
}

.ost-rank .download-ios:after {
  background-position: -60px 0;
}

.ost-rank .download-android:after {
  background-position: -90px 0;
}

