    prototype.filterInvalidChar = function (text) {
        if (text == "" || text == null) {
            return text;
        }
        text = text.replace("alert", "").replace("eval", "");
        return text.replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#x27;').replace(/\//g, '&#x2F;');
