    prototype.sys = function () {
        var userAgent = navigator.userAgent.toLowerCase();
        var platform = navigator.platform.toLowerCase();
        var win = platform ? /win/.test(platform) : /win/.test(userAgent);
        var mac = platform ? /mac/.test(platform) : /mac/.test(userAgent);
        var ie = false;
        var firefox = false;
        var chrome = false;
        var opera = false;
        var safari = false;
        var h;
        if (h = userAgent.match(/msie ([\d.]+)/)) {
            ie = h[1];
        } else if (h = userAgent.match(/firefox\/([\d.]+)/)) {
            firefox = h[1];
        } else if (h = userAgent.match(/chrome\/([\d.]+)/)) {
            chrome = h[1];
        } else if (h = userAgent.match(/opera.([\d.]+)/)) {
            opera = h[1];
        } else if (h = userAgent.match(/version\/([\d.]+).*safari/)) {
            safari = h[1];
        }

        var playerVersion = swfobject.getFlashPlayerVersion();
        var playerInstalled;
        if (playerVersion.major == 0 && playerVersion.minor == 0 && playerVersion.release == 0) {
            playerInstalled = false;
        } else {
            playerInstalled = true;
        }

        return {
            ie: ie,
            win: win,
            mac: mac,
            safari: safari,
            chrome: chrome,
            firefox: firefox,
            opera: opera,
            playerInstalled: playerInstalled
        }
    }();

    prototype.createEntrySwfObject = function (attributes, param, id, a) {
        var element = document.getElementById(id);
        if (element) {

            if (!this.sys.chrome && !this.sys.playerInstalled) {
                element.parentNode.innerHTML = '<div id="flashAlert" style="font-size:18px; color: #FFFFFF;">您还没有安装flash播放器,请点击<a href="https://www.adobe.com/support/flashplayer/debug_downloads.html" target="_blank">这里</a>安装</div>';
                return;
            }


            if (typeof attributes.id == "undefined") attributes.id = id;

            var attrStr = "";
            for (var attr in attributes) {
                if (attributes[attr] != Object.prototype[attr]) {
                    if ("data" == attr.toLowerCase()) {
                        param.movie = attributes[attr];
                    }
                    else {
                        if ("id" == attr.toLowerCase()) {
                            if (this.sys.ie) {
                                attrStr += " " + attr + '="' + attributes[attr] + '"';
                            }
                        }
                        else {
                            attrStr += " " + attr + '="' + attributes[attr] + '"';
                        }
                    }
                }

            }
            attrStr += " " + "style=display:block;text-align:center;";

            var paramStr = "";
            for (var d in param) {
                if (param[d] != Object.prototype[d])
                    paramStr += '<param name="' + d + '" value="' + param[d] + '" />';
            }
            var htmlStr = "";

            var embedStr = '<embed';
            embedStr += ' ' + 'src=' + '"' + param.movie + '"';
            embedStr += ' ' + 'type="application/x-shockwave-flash"';
            embedStr += ' ' + 'pluginspage="http://www.adobe.com/go/getflashplayer"';
            embedStr += ' ' + 'quality="high"';
            embedStr += ' ' + 'width="' + attributes.width + '"';
            embedStr += ' ' + 'height="' + attributes.height + '"';
            embedStr += ' ' + 'align="middle"';
            embedStr += ' ' + 'allowScriptAccess="' + param.allowScriptAccess + '"';
            embedStr += ' ' + 'allowFullScreenInteractive="' + param.allowFullScreenInteractive + '"';
            embedStr += ' ' + 'wmode="' + param.wmode + '"';
            embedStr += ' ' + 'name="' + attributes.name + '"';
            embedStr += ' ' + 'id="' + attributes.id + '"';
            embedStr += '>';

            htmlStr += '<object classid="clsid:d27cdb6e-ae6d-11cf-96b8-444553540000" codebase="http://fpdownload.macromedia.com/get/flashplayer/current/swflash.cab" ' + attrStr + ">" + paramStr;
