var lazyLoaderMaps = [];
var lazyLoaderMaxThread = 2;
function lazyLoader(url0,url1,url2,url3,url4) {
    if (url0 != undefined) {
        lazyLoaderMaps.push(url0);
    }
    if (url1 != undefined) {
        lazyLoaderMaps.push(url1);
    }
    if (url2 != undefined) {
        lazyLoaderMaps.push(url2);
    }
    if (url3 != undefined) {
        lazyLoaderMaps.push(url3);
    }
    if (url4 != undefined) {
        lazyLoaderMaps.push(url4);
    }
    lazyLoaderStart();
}
function lazyLoaderStart() {
    if (lazyLoaderMaps.length == 0) {
        lazyLoaderRun = false;
        return;
    }

    for (var i = 0; i < lazyLoaderMaps.length; i++) {
        currentFile = lazyLoaderMaps[i];
        tag = Math.random();
        if (currentFile.substr(-4) == ".jpg" || currentFile.substr(-4) == ".png") {
            lazyLoaderQueue().append("<img src='" + currentFile + "' id='lazyLoaderPIC_" + tag + "'  width='0' height='0' />  ");
        }
        else if (currentFile.substr(-4) == ".swf") {
            lazyLoaderQueue().append("<div id='lazyLoaderSwf_" + tag + "' ></div>  ");
            swfobject.embedSWF(currentFile, "lazyLoaderSwf_" + tag + "", "0", "0", swfVersionStr, xiSwfUrlStr);
        }
        else if (currentFile.substr(-4) == ".xml") {
            lazyLoaderQueue().append("<iframe src='" + currentFile + "' 'lazyLoaderXML_" + tag + "' width='0' height='0' />  ");
        }

    }
    lazyLoaderMaps = [];
}
function lazyLoaderQueue() {
    var childNum = $("#lazyLoader").children().length;
    if (childNum < lazyLoaderMaxThread) {
        $("#lazyLoader").append("<div id='lzL_" + childNum + "'></div>");
        return $("#lzL_" + childNum);
    }
    else {
        for (var i = 0; i < lazyLoaderMaxThread; i++) {
            if (i == 0) {
                $("#lzL_" + i).attr("id", "lzL_tmp")
            }
            else {
                $("#lzL_" + i).attr("id", "lzL_" + (i - 1))
            }
        }
        $("#lzL_tmp").attr("id", "lzL_" + (lazyLoaderMaxThread - 1))
        $("#lzL_" + (lazyLoaderMaxThread - 1)).html("");
        return $("#lzL_" + (lazyLoaderMaxThread - 1));
    }
}


