/**
 * 窗口最小化检测
 * @usage 利用浏览器的Page Visibility API(PVA)特性来检测
 * @author larryhou
 */ 
 function detectInstall()
 {
	var property, type;
	if ("hidden" in document)
	{
		property = "hidden";
		type = "visibilitychange";
	}
	else
	if ("mozHidden" in document)
	{
		property = "mozHidden";
		type = "mozvisibilitychange";
	}
	else
	if ("msHidden" in document)
	{
		property = "msHidden";
		type = "msvisibilitychange";
	}
	else
	if ("webkitHidden" in document)
	{
		property = "webkitHidden";
		type = "webkitvisibilitychange";
	}
	
	if ("addEventListener" in document || "attachEvent" in document)
	{
		if (property)
		{
			// 对于支持PVA的浏览器进行最小化和页签切换检测
			attachEvent(type, document, visibilityChangeHandler);
		}
		else
		{
			var cache = true;
			setInterval(function ()
			{
				var visible = true;
				if ("outerWidth" in window)
				{
					if (window.outerWidth <= 160 && window.outerHeight <= 27) visible = false;
				}
				else
				{
					if (window.screenTop <= -30000 && window.screenLeft <= -30000) visible = false;
				}
				
				if (cache != visible)
				{
					cache = visible;
					visibilityUpdate(visible);
				}
			}, 500);
		}
	}
	
	// 跨浏览器事件侦听
	function attachEvent(type, target, callback)
	{
		if ("addEventListener" in target)
		{
			target.addEventListener(type, callback, false);
		}
		else
		if ("attachEvent" in target)
		{
			target.attachEvent("on" + type, callback);
		}
		else
		{
			console.log("cannot listen on " + type);
		}
	}

	// PVA浏览器通知处理
	function visibilityChangeHandler()
	{
		visibilityUpdate(!Boolean(document[property]));
	}
	
	// 处理窗口不可见具体逻辑
	function visibilityUpdate(visible)
	{
		console.log((visible? "return" : "leave") + ", " + new Date().getTime());
		
		var swf = document.getElementById("entry");
		if (!swf)
		{			
			console.log("-----------------无法找到id为entry的游戏入口SWF-----------------");
			return;
		}
		
		if (swf.visibilityUpdate)
		{
			swf.visibilityUpdate(visible);
		}
	}
 }

